import type { Question } from "@/lib/types";
import { L, Q } from "./builder";

const P = "va" as const;

export const QUESTIONS_VA: Question[] = [
  Q({ id: "va-u1-01", paper: P, unitId: "va-u1", q: L("Which of the following is an element of visual art rather than a principle of composition?", "കമ്പോസിഷൻ തത്വമല്ലാത്ത, ദൃശ്യകലയുടെ എലമെന്റ് ഏത്?"), options: [L("Balance", "ബാലൻസ്"), L("Rhythm", "റിഥം"), L("Texture", "ടെക്സ്ചർ"), L("Emphasis", "എംഫസിസ്")], answer: 2, explain: L("Texture is stuff in the work (element). Balance, rhythm, emphasis are organisational relations (principles).", "ടെക്സ്ചർ എലമെന്റ്. ബാലൻസ്/റിഥം/എംഫസിസ് പ്രിൻസിപ്പിൾ."), trap: L("Texture sounds advanced so it gets filed with principles.", "ടെക്സ്ചർ അഡ്വാൻസ്ഡ് → പ്രിൻസിപ്പിൾ."), fix: L("If you can point to the stuff itself, element; if it is a relation, principle.", "വസ്തു = എലമെന്റ്. ബന്ധം = പ്രിൻസിപ്പിൾ.") }),
  Q({ id: "va-u1-02", paper: P, unitId: "va-u1", q: L("Aerial (atmospheric) perspective typically makes distant forms", "എരിയൽ പെർസ്പെക്ടീവിൽ ദൂരെയുള്ള രൂപങ്ങൾ"), options: [L("Sharper, hotter and more contrasted", "കൂടുതൽ മൂർച്ച, ചൂട്, കോൺട്രാസ്റ്റ്"), L("Lower in contrast and chroma, often cooler/greyer", "കോൺട്രാസ്റ്റും ക്രോമയും കുറഞ്ഞ്, തണുത്ത/ചാര"), L("Disappear into a vanishing point by rule of thirds only", "റൂൾ ഓഫ് തേർഡ്സ് മാത്രം കൊണ്ട് വാനിഷിംഗ് പോയിന്റിൽ"), L("Always black outlines", "എപ്പോഴും കറുത്ത ഔട്ട്‌ലൈൻ")], answer: 1, explain: L("Air scatters light: distance loses contrast and saturation. Linear perspective is the vanishing-point system.", "വായു പ്രകാശം ചിതറിക്കുന്നു. ലീനിയർ = വാനിഷിംഗ് പോയിന്റ്."), trap: L("All perspective = vanishing point.", "എല്ലാ പെർസ്പെക്ടീവും വാനിഷിംഗ് പോയിന്റ്."), fix: L("Linear = geometry of lines. Aerial = weather of colour/value.", "ലീനിയർ രേഖ. എരിയൽ നിറം.") }),
  Q({ id: "va-u1-03", paper: P, unitId: "va-u1", q: L("Foreshortening is best defined as", "ഫോർഷോർട്ടനിംഗ്"), options: [L("A kind of printmaking ink", "ഒരു പ്രിന്റ് മഷി"), L("Compressing the apparent length of a form receding in depth", "ആഴത്തിലേക്ക് പോകുന്ന രൂപത്തിന്റെ ദൃശ്യനീളം ചുരുക്കൽ"), L("Symmetrical balance only", "സമമിതി ബാലൻസ് മാത്രം"), L("A folk painting of Maharashtra", "മഹാരാഷ്ട്രയിലെ നാടൻ ചിത്രം")], answer: 1, explain: L("A raised foot looks shorter because it recedes — perspective applied to the body.", "ഉയർത്തിയ കാൽ ചെറുതായി കാണുന്നു."), trap: L("Treating it as an element like line or colour.", "രേഖ/നിറം പോലെ എലമെന്റ്."), fix: L("Syllabus lists it among principles/devices, not materials.", "തത്വ/ഉപകരണം, മെറ്റീരിയലല്ല.") }),
  Q({ id: "va-u1-04", paper: P, unitId: "va-u1", q: L("Complementary colours in subtractive (painter’s) mixing include", "സബ്ട്രാക്റ്റീവ് മിശ്രണത്തിൽ കോംപ്ലിമെന്ററി"), options: [L("Red–green, blue–orange, yellow–violet", "ചുവപ്പ്–പച്ച, നീല–ഓറഞ്ച്, മഞ്ഞ–വയലറ്റ്"), L("Red–red, blue–blue", "ചുവപ്പ്–ചുവപ്പ്"), L("Only black–white", "കറുപ്പ്–വെളുപ്പ് മാത്രം"), L("Gold–silver", "സ്വർണം–വെള്ളി")], answer: 0, explain: L("Opposites on the traditional RYB wheel. Mixing tends toward grey; juxtaposition heightens contrast.", "RYB വീലിലെ എതിർ. കലർത്തിയാൽ ചാരം."), trap: L("RGB additive complements leaking in from screen design.", "RGB ജോടികൾ ചോരുന്നു."), fix: L("Painting questions assume RYB unless they say RGB/light.", "ചിത്രചോദ്യം RYB.") }),
  Q({ id: "va-u1-05", paper: P, unitId: "va-u1", q: L("Negative space refers to", "നെഗറ്റീവ് സ്പേസ്"), options: [L("The ground around and between figures", "രൂപങ്ങൾക്ക് ചുറ്റും/ഇടയിലുള്ള ഗ്രൗണ്ട്"), L("Always a sad subject", "എപ്പോഴും ദുഃഖ വിഷയം"), L("Only sculpture bases", "ശില്പ പീഠം മാത്രം"), L("A type of intaglio acid", "ഇന്റാഗ്ലിയോ ആസിഡ്")], answer: 0, explain: L("Figure = positive. Ground = negative. Both are compositional material.", "ഫിഗർ പോസിറ്റീവ്. ഗ്രൗണ്ട് നെഗറ്റീവ്."), trap: L("Emotional reading of the word negative.", "നെഗറ്റീവ് = ദുഃഖം."), fix: L("Space words are geometry, not mood.", "സ്പേസ് വാക്കുകൾ ജ്യാമിതി.") }),
  Q({ id: "va-u1-06", paper: P, unitId: "va-u1", q: L("Asymmetrical balance means", "അസമമിതി ബാലൻസ്"), options: [L("The two halves are mirror copies", "രണ്ട് പകുതിയും കണ്ണാടി പകർപ്പ്"), L("Visual weights differ in shape/size but still equilibrate", "ആകൃതി/വലുപ്പം വ്യത്യസ്തമെങ്കിലും ദൃശ്യഭാരം സന്തുലിതം"), L("No focal point is allowed", "ഫോക്കൽ പോയിന്റ് നിരോധിച്ചിരിക്കുന്നു"), L("The work must be circular", "കൃതി വൃത്തമായിരിക്കണം")], answer: 1, explain: L("A large dull mass can balance a small intense accent. Three kinds: symmetrical, asymmetrical, radial.", "മൂന്ന് ബാലൻസ്: സമമിതി, അസമമിതി, റേഡിയൽ."), trap: L("Balance = symmetry only.", "ബാലൻസ് = സമമിതി മാത്രം."), fix: L("Memorise the triad of balances.", "മൂന്ന് ബാലൻസ് ജപിക്കുക.") }),
  Q({ id: "va-u1-07", paper: P, unitId: "va-u1", q: L("Tonal value is", "ടോണൽ വാല്യൂ"), options: [L("The lightness–darkness scale that models volume", "വോളിയം കട്ടിയാക്കുന്ന ഇളം–ഇരുണ്ട സ്കെയിൽ"), L("Always the same as hue", "ഹ്യൂവിന് തുല്യം"), L("A Mughal court rank", "മുഗൾ ദർബാർ റാങ്ക്"), L("A type of wasli polish", "വാസ്ലി പോളിഷ്")], answer: 0, explain: L("Hue = colour family. Value = light/dark. Chroma = intensity.", "ഹ്യൂ, വാല്യൂ, ക്രോമ."), trap: L("Tone in music or Paper I comprehension leaking across.", "സംഗീത/കോംപ്രഹെൻഷൻ ടോൺ."), fix: L("Painting tone = grey scale. Three-word card: hue, value, chroma.", "ഹ്യൂ വാല്യൂ ക്രോമ.") }),
  Q({ id: "va-u1-08", paper: P, unitId: "va-u1", q: L("2D representation as against 3D in the syllabus mainly distinguishes", "സിലബസിലെ 2D vs 3D പ്രധാനമായും വേർതിരിക്കുന്നത്"), options: [L("Painting/print/drawing from sculpture/installation occupying real space", "യഥാർഥ സ്ഥലം പിടിക്കുന്ന ശില്പ/ഇൻസ്റ്റലേഷനിൽ നിന്ന് ചിത്ര/പ്രിന്റ്/ഡ്രോയിംഗ്"), L("Indian from Western art", "ഇന്ത്യൻ vs പാശ്ചാത്യ"), L("Folk from classical only", "നാടൻ vs ക്ലാസിക്കൽ മാത്രം"), L("Digital from analogue dates", "ഡിജിറ്റൽ vs അനലോഗ് തീയതി")], answer: 0, explain: L("Same principles on a plane and in mass/site. Installation is 3D even if it uses pictures.", "ഇൻസ്റ്റലേഷൻ ചിത്രം ഉപയോഗിച്ചാലും 3D."), trap: L("2D = primitive, 3D = advanced — a value judgement NTA does not want.", "2D പ്രാകൃതം എന്ന മൂല്യവിധി."), fix: L("Does the viewer walk around it? Yes → 3D situation.", "ചുറ്റി നടക്കുന്നുണ്ടോ?") }),
  Q({ id: "va-u2-01", paper: P, unitId: "va-u2", q: L("Ragamala paintings primarily visualise", "രാഗമാല ചിത്രങ്ങൾ പ്രധാനമായും ദൃശ്യമാക്കുന്നത്"), options: [L("Stock-market charts", "ഓഹരി ചാർട്ട്"), L("Musical ragas as poetic-pictorial sets", "സംഗീത രാഗങ്ങളെ കാവ്യ-ചിത്ര സെറ്റായി"), L("Only Buddhist jatakas", "ബൗദ്ധ ജാതകം മാത്രം"), L("Railway maps", "റെയിൽവേ മാപ്പ്")], answer: 1, explain: L("Rajasthani, Pahari and Deccani sets pair raga, time, deity, lovers — a syllabus-perfect inter-art case.", "രാഗം, സമയം, ദേവത, നായികാനായകൻ."), trap: L("Mala → jewellery. Or raga → only the performing-art paper.", "മാല = ആഭരണം."), fix: L("Unit II keyword: named crossovers. Lock Ragamala first.", "പേരുള്ള ക്രോസ്ഓവർ.") }),
  Q({ id: "va-u2-02", paper: P, unitId: "va-u2", q: L("Eisenstein’s montage is to cinema what collage is to", "സിനിമയ്ക്ക് ഐസൻസ്റ്റൈൻ മോണ്ടാജ് എന്നത് ചിത്രത്തിന്"), options: [L("Buon fresco", "ബുവോൺ ഫ്രെസ്കോ"), L("Modern pictorial construction from fragments", "ശകലങ്ങളിൽ നിന്നുള്ള ആധുനിക ചിത്രനിർമാണം"), L("Ashokan polish", "അശോകൻ പോളിഷ്"), L("Nagara shikhara", "നാഗര ശിഖരം")], answer: 1, explain: L("Both assemble meaning by juxtaposition rather than continuous modelling.", "ജക്സ്റ്റാപ്പോസിഷൻ കൊണ്ട് അർഥം."), trap: L("Picking an Indian architecture term because this is Visual Art India.", "ഇന്ത്യൻ വാസ്തു പദം."), fix: L("Analogy questions: match the operation, not the civilisation.", "പ്രക്രിയ യോജിപ്പിക്കുക, നാഗരികമല്ല.") }),
  Q({ id: "va-u2-03", paper: P, unitId: "va-u2", q: L("Ekphrasis is", "ഏക്ഫ്രാസിസ്"), options: [L("A lost-wax tool", "ലോസ്റ്റ്-വാക്സ് ഉപകരണം"), L("Literary description of a visual artwork", "ദൃശ്യകലാസൃഷ്ടിയുടെ സാഹിത്യ വിവരണം"), L("A Gestalt law", "ഗെസ്റ്റാൾട്ട് നിയമം"), L("A Kyoto Protocol annex", "ക്യോട്ടോ അനെക്സ്")], answer: 1, explain: L("Keats’s urn; Sanskrit chitra-kavya. Literature meeting visual art.", "കീറ്റ്സ്; ചിത്രകാവ്യം."), trap: L("Greek word → pick Gestalt.", "ഗ്രീക്ക് പദം → ഗെസ്റ്റാൾട്ട്."), fix: L("Ekphrasis is Unit II. Gestalt is Unit X.", "ഏക്ഫ്രാസിസ് II. ഗെസ്റ്റാൾട്ട് X.") }),
  Q({ id: "va-u2-04", paper: P, unitId: "va-u2", q: L("Ajanta is a strong Unit II example because it", "അജന്ത യൂണിറ്റ് II ഉദാഹരണം — കാരണം"), options: [L("Is only a British oil canvas", "ബ്രിട്ടീഷ് ഓയിൽ ക്യാൻവാസ് മാത്രം"), L("Fuses painting, sculpture and architecture as one visual programme", "ചിത്രം, ശില്പം, വാസ്തു ഒരു ദൃശ്യപരിപാടിയായി ലയിപ്പിക്കുന്നു"), L("Has no narrative", "ആഖ്യാനമില്ല"), L("Is a ukiyo-e series", "ഉക്യോ-ഇ സീരീസ്")], answer: 1, explain: L("Caves are architecture; Buddha images sculpture; walls painting.", "ഗുഹ വാസ്തു; ബുദ്ധ ശില്പം; ചുവർ ചിത്രം."), trap: L("Filing Ajanta only in Unit VII chronology.", "യൂണിറ്റ് VII മാത്രം."), fix: L("Tag Ajanta as VII-chronology AND II-ensemble.", "രണ്ട് ടാഗ്.") }),
  Q({ id: "va-u2-05", paper: P, unitId: "va-u2", q: L("Satyajit Ray is useful for this unit because he", "സത്യജിത് റേ ഈ യൂണിറ്റിന് ഉപയോഗപ്രദം — അദ്ദേഹം"), options: [L("Only wrote the Natyashastra", "നാട്യശാസ്ത്രം മാത്രം എഴുതി"), L("Worked across cinema, graphic design, type and music", "സിനിമ, ഗ്രാഫിക് ഡിസൈൻ, ടൈപ്പ്, സംഗീതം കുറുകെ പ്രവർത്തിച്ചു"), L("Founded the Progressive Artists’ Group in Bombay", "ബോംബെയിൽ PAG സ്ഥാപിച്ചു"), L("Carved the Didarganj Yakshi", "ദീദാർഗഞ്ച് യക്ഷി കൊത്തി")], answer: 1, explain: L("Ray designed posters and credits, composed, and framed like a painter.", "പോസ്റ്റർ, ക്രെഡിറ്റ്, സംഗീതം, ഫ്രെയിം."), trap: L("Famous Bengali name → Bengal School / PAG.", "ബംഗാളി പേര് → PAG."), fix: L("Ray = cinema+design. PAG = Souza/Raza/Husain 1947.", "റേ ≠ PAG.") }),
  Q({ id: "va-u2-06", paper: P, unitId: "va-u2", q: L("The Bauhaus matters to Unit II because it", "ബോഹൗസ് യൂണിറ്റ് II-ൽ പ്രധാനം — അത്"), options: [L("Collapsed craft, design, theatre and fine art into one pedagogy", "ക്രാഫ്റ്റ്, ഡിസൈൻ, തിയേറ്റർ, ഫൈൻ ആർട്ട് ഒരു പെഡഗോജിയിലാക്കി"), L("Was a Chola bronze foundry", "ചോള വെങ്കല ലോഹശാല"), L("Wrote the Paris Agreement", "പാരീസ് ഉടമ്പടി എഴുതി"), L("Is a Warli village", "വാർലി ഗ്രാമം")], answer: 0, explain: L("Gropius refused the fine/applied split — architecture, theatre, workshop, painting together.", "ഫൈൻ/അപ്ലൈഡ് വിഭജനം നിരാകരിച്ചു."), trap: L("Bauhaus as merely a chair style.", "ബോഹൗസ് കസേര ശൈലി മാത്രം."), fix: L("Multidisciplinary Western pick = Bauhaus. Indian cousin = Santiniketan.", "ബോഹൗസ് / ശാന്തിനികേതൻ.") }),
  Q({ id: "va-u2-07", paper: P, unitId: "va-u2", q: L("Kathakali makeup can be discussed in Visual Art as", "കഥകളി മേക്കപ്പ് ദൃശ്യകലയിൽ"), options: [L("Graphic design on the face, colour-coded character types", "മുഖത്തെ ഗ്രാഫിക് ഡിസൈൻ, നിറം-കോഡഡ് കഥാപാത്ര തരങ്ങൾ"), L("A type of mezzotint", "മെസോറ്റിന്റ്"), L("Gandhara schist polish", "ഗന്ധാര ഷിസ്റ്റ് പോളിഷ്"), L("SMTP protocol", "SMTP")], answer: 0, explain: L("Green, katti, tadi — visual language shared with performing art. Syllabus names performing art explicitly.", "പച്ച, കത്തി, താടി. സിലബസ് പെർഫോമിംഗ് ആർട്ട് പറയുന്നു."), trap: L("Dance is Paper 65 so ignore it.", "നൃത്തം പേപ്പർ 65."), fix: L("Keep four Indian stage-visual examples.", "നാല് സ്റ്റേജ്-ദൃശ്യ ഉദാഹരണം.") }),
  Q({ id: "va-u2-08", paper: P, unitId: "va-u2", q: L("Rasa theory is an inter-art tool because it", "രസസിദ്ധാന്തം ഇന്റർ-ആർട്ട് ഉപകരണം — കാരണം"), options: [L("Applies only to oil on canvas in Paris 1874", "1874 പാരീസ് ഓയിലിന് മാത്രം"), L("Was formulated for theatre yet used to read poetry, music and visual narrative", "നാടകത്തിന് രൂപപ്പെട്ടെങ്കിലും കവിത, സംഗീതം, ദൃശ്യാഖ്യാനം വായിക്കാൻ ഉപയോഗിക്കുന്നു"), L("Is a Kyoto climate annex", "ക്യോട്ടോ അനെക്സ്"), L("Rejects all feeling", "എല്ലാ വികാരവും നിരാകരിക്കുന്നു")], answer: 1, explain: L("Natyashastra is theatre, but rasa became a pan-Indian aesthetic. Units II and V share this spine.", "രസം പാൻ-ഇന്ത്യൻ. യൂണിറ്റ് II+V."), trap: L("Keeping rasa locked in Unit V only.", "രസം യൂണിറ്റ് V മാത്രം."), fix: L("If the stem says cinema/poetry/painting together, rasa is fair game.", "സിനിമ/കവിത/ചിത്രം → രസം.") }),
  Q({ id: "va-u3-01", paper: P, unitId: "va-u3", difficulty: "jrf", q: L("Wasli is", "വാസ്ലി"), options: [L("A laminated, burnished paper ground for Indian miniatures", "ഇന്ത്യൻ മിനിയേച്ചറിനുള്ള പാളിയിട്ട് തേച്ച കടലാസ് ഗ്രൗണ്ട്"), L("A Chola lost-wax bronze", "ചോള ലോസ്റ്റ്-വാക്സ് വെങ്കലം"), L("An etching acid", "എച്ചിംഗ് ആസിഡ്"), L("A Bauhaus workshop", "ബോഹൗസ് വർക്ക്‌ഷോപ്പ്")], answer: 0, explain: L("Sheets glued, dried, burnished with agate — takes a fine brush. Syllabus names wasli explicitly.", "അഗേറ്റ് തേപ്പ്. സിലബസ് പേരെടുത്ത്."), trap: L("Any Indian paper word → palm leaf.", "ഇന്ത്യൻ പേപ്പർ → താളിയോല."), fix: L("Miniature ground = wasli. Palm leaf = manuscript, different technology.", "മിനിയേച്ചർ = വാസ്ലി.") }),
  Q({ id: "va-u3-02", paper: P, unitId: "va-u3", q: L("Etching belongs to which print family?", "എച്ചിംഗ് ഏത് പ്രിന്റ് കുടുംബം"), options: [L("Relief (like woodcut)", "റിലീഫ് (വുഡ്കട്ട് പോലെ)"), L("Intaglio (ink in bitten grooves)", "ഇന്റാഗ്ലിയോ (കടിച്ച പോട്ടുകളിൽ മഷി)"), L("Only screenprint stencil", "സ്ക്രീൻ സ്റ്റെൻസിൽ മാത്രം"), L("Only digital giclée", "ഡിജിറ്റൽ ജിക്ലേ മാത്രം")], answer: 1, explain: L("Acid bites metal; ink wiped into lines; press pushes paper in. Woodcut is relief — physically opposite.", "ആസിഡ് കടിക്കുന്നു. വുഡ്കട്ട് റിലീഫ്."), trap: L("Cut in etching/engraving → relief.", "കട്ട് കേട്ടാൽ റിലീഫ്."), fix: L("High prints = relief. Low prints = intaglio. Flat = litho. Stencil = serigraph.", "ഉയർന്നത് റിലീഫ്. താഴ്ന്നത് ഇന്റാഗ്ലിയോ.") }),
  Q({ id: "va-u3-03", paper: P, unitId: "va-u3", q: L("Chola bronzes are classically made by", "ചോള വെങ്കലങ്ങൾ പരമ്പരാഗതമായി"), options: [L("Buon fresco on wet lime", "നനഞ്ഞ കുമ്മായത്തിൽ ബുവോൺ ഫ്രെസ്കോ"), L("Lost-wax (cire perdue) casting", "ലോസ്റ്റ്-വാക്സ് (സിരെ പെർദ്യൂ) കാസ്റ്റിംഗ്"), L("Ukiyo-e woodblock", "ഉക്യോ-ഇ വുഡ്ബ്ലോക്ക്"), L("Only carving sandstone like Khajuraho", "ഖജുരാഹോ പോലെ മണൽക്കൽ കൊത്തൽ മാത്രം")], answer: 1, explain: L("Wax model, clay mould, wax melted out, metal poured — hollow, processional.", "മെഴുക് മാതൃക, ലോഹം, ഘോഷയാത്ര."), trap: L("All Indian sacred images = stone carving.", "എല്ലാ വിഗ്രഹവും കൽക്കൊത്തൽ."), fix: L("South Indian processional god = bronze + lost-wax until proven otherwise.", "ഉത്സവ വിഗ്രഹം = വെങ്കലം.") }),
  Q({ id: "va-u3-04", paper: P, unitId: "va-u3", q: L("Buon fresco differs from fresco secco because buon fresco", "ബുവോൺ ഫ്രെസ്കോ സെക്കോയിൽ നിന്ന് വ്യത്യസ്തം — ബുവോൺ"), options: [L("Is painted into wet intonaco so pigment binds chemically", "നനഞ്ഞ ഇന്റോനാകോയിൽ പെയിന്റ് ചെയ്ത് പിഗ്മെന്റ് രാസബന്ധം"), L("Is always acrylic on canvas", "എപ്പോഴും ക്യാൻവാസിലെ അക്രിലിക്"), L("Is a Japanese woodblock step", "ജാപ്പനീസ് വുഡ്ബ്ലോക്ക് ഘട്ടം"), L("Uses only wax (encaustic)", "മെഴുക് മാത്രം (എൻകോസ്റ്റിക്)")], answer: 0, explain: L("True fresco: pigment in wet lime. Secco: dry plaster, weaker bond.", "യഥാർഥ ഫ്രെസ്കോ നനവ്. സെക്കോ ഉണക്ക്."), trap: L("Fresco = any mural.", "ഫ്രെസ്കോ = ഏത് മ്യൂറലും."), fix: L("Buon = wet. Secco = dry.", "Buon നനവ്. Secco ഉണക്ക്.") }),
  Q({ id: "va-u3-05", paper: P, unitId: "va-u3", q: L("Impasto as against glazing is", "ഗ്ലേസിന് എതിരെ ഇമ്പാസ്റ്റോ"), options: [L("Thin transparent films of oil", "നേർത്ത സുതാര്യ എണ്ണ പാളികൾ"), L("Thick, physically ridged paint", "കട്ടിയുള്ള, ഭൗതികമായി ഉയർന്ന പെയിന്റ്"), L("A wasli burnish", "വാസ്ലി തേപ്പ്"), L("A type of litho stone", "ലിത്തോ കല്ല്")], answer: 1, explain: L("Impasto catches light on ridges. Glaze is transparent layering over an underpainting.", "ഇമ്പാസ്റ്റോ വരമ്പ്. ഗ്ലേസ് സുതാര്യ പാളി."), trap: L("Both oil techniques feel synonymous.", "രണ്ടും ഓയിൽ — പര്യായം."), fix: L("If it casts a micro-shadow, impasto.", "മൈക്രോ ഷാഡോ = ഇമ്പാസ്റ്റോ.") }),
  Q({ id: "va-u3-06", paper: P, unitId: "va-u3", q: L("Woodcut is a relief process because", "വുഡ്കട്ട് റിലീഫ് — കാരണം"), options: [L("Ink sits in the cut grooves and is wiped in", "മഷി മുറിച്ച പോട്ടിൽ തുടച്ചിടുന്നു"), L("The raised, uncut surface is inked and prints", "മുറിക്കാത്ത ഉയർന്ന പ്രതലത്തിൽ മഷി തേച്ച് അച്ചടിക്കുന്നു"), L("It uses a litho grease crayon", "ലിത്തോ ഗ്രീസ് ക്രയോൺ"), L("It is always photographic", "എപ്പോഴും ഫോട്ടോഗ്രാഫിക്")], answer: 1, explain: L("Cut away what should stay white; the high remaining wood prints. Like a rubber stamp.", "വെളുത്ത് നിൽക്കേണ്ടത് മുറിക്കുക. റബ്ബർ സ്റ്റാമ്പ്."), trap: L("All cutting = intaglio engraving.", "എല്ലാ മുറിക്കലും ഇന്റാഗ്ലിയോ."), fix: L("Rubber stamp = relief = woodcut.", "സ്റ്റാമ്പ് = റിലീഫ്.") }),
  Q({ id: "va-u3-07", paper: P, unitId: "va-u3", q: L("Carving as against modelling is", "മോഡലിംഗിന് എതിരെ കൊത്തൽ"), options: [L("Subtractive (stone, wood) versus additive (clay)", "കുറയ്ക്കൽ (കല്ല്, മരം) vs ചേർക്കൽ (കളിമണ്ണ്)"), L("Always bronze versus always wax", "എപ്പോഴും വെങ്കലം vs മെഴുക്"), L("2D versus digital", "2D vs ഡിജിറ്റൽ"), L("Folk versus classical only", "നാടൻ vs ക്ലാസിക്കൽ മാത്രം")], answer: 0, explain: L("Carving removes. Modelling adds. Casting copies a model into metal.", "കൊത്തൽ നീക്കം. മോഡലിംഗ് ചേർക്കൽ. കാസ്റ്റിംഗ് പകർപ്പ്."), trap: L("All sculpture = carving, because temples.", "ക്ഷേത്രം കാരണം എല്ലാം കൊത്തൽ."), fix: L("Ramkinkar’s outdoor cement is modelled/constructed, not Chola-carved.", "രാംകിങ്കർ മോഡൽ/കൺസ്ട്രക്ട്.") }),
  Q({ id: "va-u3-08", paper: P, unitId: "va-u3", q: L("Aquatint is used in intaglio to", "ഇന്റാഗ്ലിയോയിൽ അക്വാറ്റിന്റ്"), options: [L("Create tonal areas, not only lines", "രേഖകൾ മാത്രമല്ല, ടോണൽ ഏരിയകൾ"), L("Print from a wooden plank’s surface", "മരപ്പലകയുടെ പ്രതലത്തിൽ നിന്ന്"), L("Polish wasli", "വാസ്ലി തേക്കുക"), L("Cast bronze", "വെങ്കലം കാസ്റ്റ് ചെയ്യുക")], answer: 0, explain: L("Rosin dust lets acid bite a grainy tone — Goya’s Caprichos mood.", "റോസിൻ പൊടി ടോൺ. ഗോയ."), trap: L("Aqua- → watercolour on paper.", "Aqua → വാട്ടർകളർ."), fix: L("Aqua in print = tone on metal, still intaglio.", "പ്രിന്റിലെ aqua = ലോഹ ടോൺ.") }),
  Q({ id: "va-u4-01", paper: P, unitId: "va-u4", difficulty: "jrf", q: L("A vector file, unlike a raster file,", "റാസ്റ്ററിൽ നിന്ന് വ്യത്യസ്തമായി വെക്ടർ ഫയൽ"), options: [L("Is a grid of pixels and pixelates when enlarged", "പിക്സൽ ഗ്രിഡ്, വലുതാക്കിയാൽ പിക്സലേറ്റ്"), L("Stores mathematical paths and can scale without jaggies", "ഗണിത പാതകൾ സൂക്ഷിക്കുന്നു, ജാഗി ഇല്ലാതെ സ്കെയിൽ ചെയ്യാം"), L("Cannot be used for logos", "ലോഗോയ്ക്ക് ഉപയോഗിക്കാനാവില്ല"), L("Is always a photograph", "എപ്പോഴും ഫോട്ടോഗ്രാഫ്")], answer: 1, explain: L("SVG/AI/Bezier = vector (logos, type). JPEG/TIFF bitmaps = raster (photos).", "ലോഗോ = വെക്ടർ. ഫോട്ടോ = റാസ്റ്റർ."), trap: L("All computer images are pixels in everyday speech.", "ദൈനംദിന ഭാഷയിൽ എല്ലാം പിക്സൽ."), fix: L("Logo from visiting card to billboard must be vector.", "ബിൽബോർഡ് ലോഗോ = വെക്ടർ.") }),
  Q({ id: "va-u4-02", paper: P, unitId: "va-u4", q: L("Installation art typically", "ഇൻസ്റ്റലേഷൻ ആർട്ട് സാധാരണ"), options: [L("Is a portable easel picture only", "എളുപ്പം എടുത്തുകൊണ്ടുപോകാവുന്ന ഈസൽ ചിത്രം മാത്രം"), L("Occupies and redefines a site; the viewer enters it", "ഒരു സ്ഥലത്തെ പുനർനിർവചിച്ച് കാഴ്ചക്കാരൻ അകത്ത് കടക്കുന്നു"), L("Is always a Chola bronze", "എപ്പോഴും ചോള വെങ്കലം"), L("Cannot use sound or video", "ശബ്ദമോ വീഡിയോയോ അനുവദിക്കില്ല")], answer: 1, explain: L("Not just sculpture on a plinth — space, duration, sometimes ephemerality.", "പീഠത്തിലെ ശില്പം മാത്രമല്ല."), trap: L("Any 3D object = installation.", "ഏത് 3D-യും ഇൻസ്റ്റലേഷൻ."), fix: L("Is the room part of the work? Yes → installation.", "മുറി കൃതിയുടെ ഭാഗമോ?") }),
  Q({ id: "va-u4-03", paper: P, unitId: "va-u4", q: L("Trompe-l’œil means", "ട്രോമ്പ്-ലോയ്"), options: [L("Fooling the eye with illusionistic depth/objecthood on a flat plane", "തലത്തിൽ ആഴം/വസ്തുത്വം കാണിച്ച് കണ്ണിനെ പറ്റിക്കൽ"), L("A folk triangle language of Warli", "വാർലിയുടെ ത്രികോണ ഭാഷ"), L("A Kyoto Protocol mechanism", "ക്യോട്ടോ മെക്കാനിസം"), L("A type of wasli glue", "വാസ്ലി പശ")], answer: 0, explain: L("French: deceive the eye. Baroque ceilings, painted niches, contemporary hyperrealism.", "കണ്ണിനെ പറ്റിക്കുക. ബറോക്ക് സീലിംഗ്."), trap: L("Any realism = trompe-l’œil.", "ഏത് റിയലിസവും ട്രോമ്പ്-ലോയ് അല്ല."), fix: L("If you want to touch the painted fly, it is trompe-l’œil.", "വരച്ച ഈച്ച തൊടാൻ തോന്നിയാൽ.") }),
  Q({ id: "va-u4-04", paper: P, unitId: "va-u4", q: L("Assemblage is closest to", "അസംബ്ലേജ് ഏറ്റവും അടുത്തത്"), options: [L("Composing a work from found objects", "കണ്ടെത്തിയ വസ്തുക്കൾ കൊണ്ട് കൃതി ചേർക്കൽ"), L("Only buon fresco giornate", "ബുവോൺ ഫ്രെസ്കോ ജോർനാറ്റ മാത്രം"), L("Ashokan pillar polish", "അശോക സ്തംഭ പോളിഷ്"), L("A Nagara rekha-deul moulding course", "നാഗര രേഖ-ദേവൽ മോൾഡിംഗ്")], answer: 0, explain: L("Picasso/Duchamp through bricolage to contemporary Indian found-object work. 3D collage.", "ഫൗണ്ട്-ഒബ്ജക്ട്. 3D കൊളാഷ്."), trap: L("Confusing assemblage with installation or with collage.", "ഇൻസ്റ്റലേഷൻ/കൊളാഷ് കൂട്ടിക്കലർത്തൽ."), fix: L("Collage = paper plane. Assemblage = objects. Installation = the room.", "തലം / വസ്തു / മുറി.") }),
  Q({ id: "va-u4-05", paper: P, unitId: "va-u4", predicted: true, q: L("Raqs Media Collective is most often discussed under", "Raqs Media Collective ഏറ്റവും കൂടുതൽ ചർച്ച ചെയ്യുന്നത്"), options: [L("Ajanta workshop painters of the 5th century", "5-ാം നൂറ്റാണ്ട് അജന്ത ചിത്രകാർ"), L("Contemporary research-based new media / installation practice from India", "ഇന്ത്യയിലെ സമകാലിക റിസർച്ച്-ആധാരിത ന്യൂ മീഡിയ / ഇൻസ്റ്റലേഷൻ"), L("The six PAG founders of 1947", "1947 PAG ആറ് സ്ഥാപകർ"), L("Ukiyo-e publishers of Edo", "എഡോ ഉക്യോ-ഇ പ്രസാധകർ")], answer: 1, explain: L("Delhi-based collective; time, urbanism, installation, video. Units IV/VIII current-cycle name.", "ഡൽഹി കളക്ടീവ്. യൂണിറ്റ് IV/VIII."), trap: L("Any collective → PAG 1947.", "ഏത് കളക്ടീവും PAG."), fix: L("1947 PAG = Bombay painters. 1990s– = research/media collectives.", "വേറെ നൂറ്റാണ്ട്.") }),
  Q({ id: "va-u4-06", paper: P, unitId: "va-u4", q: L("Giclée prints are", "ജിക്ലേ പ്രിന്റുകൾ"), options: [L("High-quality inkjet reproductions of digital files", "ഡിജിറ്റൽ ഫയലുകളുടെ ഉയർന്ന നിലവാരമുള്ള ഇങ്ക്ജെറ്റ് പകർപ്പുകൾ"), L("16th-century woodcuts only", "16-ാം നൂറ്റാണ്ട് വുഡ്കട്ട് മാത്രം"), L("Lost-wax sprues", "ലോസ്റ്റ്-വാക്സ് സ്പ്രൂ"), L("A Nagara moulding", "നാഗര മോൾഡിംഗ്")], answer: 0, explain: L("Fine-art digital print market term. Unit IV includes digital descendants of multi-colour print.", "ഡിജിറ്റൽ ഫൈൻ-ആർട്ട് പ്രിന്റ്."), trap: L("Only hand-pulled counts as printmaking.", "ഹാൻഡ്-പുൾഡ് മാത്രം പ്രിന്റ്."), fix: L("Unit IV is contemporary processes. Digital output is inside the syllabus.", "ഡിജിറ്റൽ സിലബസിനകത്ത്.") }),
  Q({ id: "va-u4-07", paper: P, unitId: "va-u4", q: L("3D printing in sculpture is conceptually closest to", "ശില്പത്തിൽ 3D പ്രിന്റ് ഏറ്റവും അടുത്തത്"), options: [L("A return from digital model to physical additive making", "ഡിജിറ്റൽ മോഡലിൽ നിന്ന് ഭൗതിക അഡിറ്റീവ് നിർമാണത്തിലേക്ക് മടക്കം"), L("Only aerial perspective", "എരിയൽ പെർസ്പെക്ടീവ് മാത്രം"), L("Bharata’s rasa-sutra", "ഭരതന്റെ രസസൂത്രം"), L("Ashokan Mauryan polish recipe", "അശോകൻ പോളിഷ് റെസിപ്പി")], answer: 0, explain: L("A digital form becomes layered matter — modelling/casting’s grandchild.", "പാളിയായ പദാർഥം — മോഡലിംഗിന്റെ പേരക്കുട്ടി."), trap: L("3D printing = only industrial design, not fine art.", "3D പ്രിന്റ് ഫൈൻ ആർട്ടല്ല."), fix: L("Digital technologies in art include objects from printers.", "പ്രിന്റർ ഒബ്ജക്ട് സിലബസിൽ.") }),
  Q({ id: "va-u4-08", paper: P, unitId: "va-u4", q: L("Video art differs from conventional cinema in the art-historical sense because it", "കലാചരിത്രത്തിൽ വീഡിയോ ആർട്ട് സാധാരണ സിനിമയിൽ നിന്ന് വ്യത്യസ്തം"), options: [L("Always has a bigger budget than Bollywood", "എപ്പോഴും ബോളിവുഡിനേക്കാൾ ബജറ്റ്"), L("Often loops, installs in galleries, and treats time as sculptural material", "പലപ്പോഴും ലൂപ്പ്, ഗാലറി ഇൻസ്റ്റാൾ, സമയത്തെ ശില്പ മാധ്യമമായി കാണുന്നു"), L("Cannot show a human figure", "മനുഷ്യരൂപം കാണിക്കില്ല"), L("Is identical to SWAYAM Prabha", "SWAYAM Prabha-യ്ക്ക് തുല്യം")], answer: 1, explain: L("Nam June Paik onward: monitor as object, loop as form, gallery as theatre. Cinema’s theatrical run is a different institution.", "മോണിറ്റർ വസ്തു, ലൂപ്പ് രൂപം, ഗാലറി തിയേറ്റർ. സിനിമയുടെ റൺ വേറെ സ്ഥാപനം."), trap: L("Any moving image = cinema = Unit II only.", "ചലിക്കുന്ന ഏത് ചിത്രവും സിനിമ = യൂണിറ്റ് II മാത്രം."), fix: L("Cinema as sister art = Unit II. Video as contemporary medium = Unit IV/VIII.", "സിനിമ യൂണിറ്റ് II. വീഡിയോ യൂണിറ്റ് IV/VIII.") }),

  Q({ id: "va-u5-01", paper: P, unitId: "va-u5", difficulty: "jrf", q: L("Bharata’s Natyashastra lists how many rasas (before Abhinavagupta’s addition)?", "അഭിനവഗുപ്തന്റെ കൂട്ടിച്ചേർക്കലിന് മുമ്പ് ഭരതന്റെ നാട്യശാസ്ത്രത്തിൽ എത്ര രസം?"), options: [L("Six", "ആറ്"), L("Eight", "എട്ട്"), L("Nine", "ഒമ്പത്"), L("Twelve", "പന്ത്രണ്ട്")], answer: 1, explain: L("Eight rasas in Bharata. Abhinavagupta’s śānta is the influential ninth. Read the stem: ‘Bharata’ → eight.", "ഭരതനിൽ എട്ട്. അഭിനവഗുപ്തന്റെ ശാന്തം ഒമ്പതാമത്. ‘ഭരതൻ’ → എട്ട്."), trap: L("School memory of ‘navarasa’ always nine.", "നവരസം എപ്പോഴും ഒമ്പത്."), fix: L("Stem police: Bharata = 8. Abhinava / later tradition = 9.", "ഭരതൻ=8. അഭിനവ=9.") }),
  Q({ id: "va-u5-02", paper: P, unitId: "va-u5", q: L("Dhvani as the soul of poetry is associated with", "കവിതയുടെ ആത്മാവായ ധ്വനി ബന്ധപ്പെട്ടത്"), options: [L("Anandavardhana’s Dhvanyaloka", "ആനന്ദവർധനന്റെ ധ്വന്യാലോകം"), L("Clive Bell", "ക്ലൈവ് ബെൽ"), L("Greenberg’s medium specificity", "ഗ്രീൻബർഗിന്റെ മീഡിയം സ്പെസിഫിസിറ്റി"), L("The Kyoto Protocol", "ക്യോട്ടോ പ്രോട്ടോക്കോൾ")], answer: 0, explain: L("Suggested meaning beyond literal (abhidha) and secondary (lakshana). Kuntaka’s vakrokti is a different school.", "അഭിധ/ലക്ഷണയ്ക്കപ്പുറം ധ്വനിതാർഥം. വക്രോക്തി വേറെ സ്കൂൾ."), trap: L("Any Sanskrit aesthetics → Bharata only.", "ഏത് സംസ്കൃത സൗന്ദര്യശാസ്ത്രവും ഭരതൻ."), fix: L("Author–book–keyword cards: Anandavardhana–Dhvanyaloka–dhvani; Kuntaka–vakrokti; Ksemendra–aucitya.", "ഗ്രന്ഥകാരൻ–ഗ്രന്ഥം–കീവേഡ് കാർഡ്.") }),
  Q({ id: "va-u5-03", paper: P, unitId: "va-u5", q: L("Clive Bell’s ‘significant form’ claims that", "ക്ലൈവ് ബെല്ലിന്റെ സിഗ്നിഫിക്കന്റ് ഫോം"), options: [L("Only the story of a painting matters", "ചിത്രത്തിന്റെ കഥ മാത്രം പ്രധാനം"), L("Relations of lines and colours provoke the aesthetic emotion", "രേഖ-നിറ ബന്ധങ്ങൾ സൗന്ദര്യവികാരം ഉണർത്തുന്നു"), L("Art must infect the viewer with the artist’s moral sermon only", "കലാകാരന്റെ ധാർമിക പ്രസംഗം മാത്രം പകരണം"), L("Beauty is never disinterested", "ഭംഗി ഒരിക്കലും നിരപേക്ഷമല്ല")], answer: 1, explain: L("Formalist slogan of early 20th-c British aesthetics. Tolstoy is infection-of-feeling; Kant is disinterested judgement — don’t mix the three.", "ഫോർമലിസ്റ്റ് മുദ്രാവാക്യം. ടോൾസ്റ്റോയ് ഇൻഫെക്ഷൻ; കാന്റ് നിരപേക്ഷ വിധി."), trap: L("All Western theorists blur into ‘form vs content’.", "എല്ലാ പാശ്ചാത്യ ചിന്തകരും ഫോം vs കണ്ടന്റ്."), fix: L("Bell = significant form. Tolstoy = infection. Kant = disinterested + sublime. Three stickers.", "ബെൽ ഫോം. ടോൾസ്റ്റോയ് ഇൻഫെക്ഷൻ. കാന്റ് നിരപേക്ഷ.") }),
  Q({ id: "va-u5-04", paper: P, unitId: "va-u5", q: L("Aristotle’s catharsis is", "അരിസ്റ്റോട്ടിലിന്റെ കാതാർസിസ്"), options: [L("A purge/clarification of pity and fear through tragedy", "ദുരന്തനാടകത്തിലൂടെ കരുണയുടെയും ഭയത്തിന്റെയും ശുദ്ധീകരണം"), L("Plato’s claim that art is twice removed from truth", "കല സത്യത്തിൽ നിന്ന് രണ്ട് പടി അകലെ എന്ന പ്ലേറ്റോ"), L("Bell’s significant form", "ബെല്ലിന്റെ സിഗ്നിഫിക്കന്റ് ഫോം"), L("A printmaking ground", "പ്രിന്റ് ഗ്രൗണ്ട്")], answer: 0, explain: L("Poetics: tragedy’s work on the spectator. Plato is the suspicious uncle; Aristotle the rehabilitator of mimesis.", "പൊയറ്റിക്സ്. പ്ലേറ്റോ സംശയാലു; അരിസ്റ്റോട്ടിൽ മിമെസിസിനെ പുനരധിവസിപ്പിക്കുന്നു."), trap: L("Plato/Aristotle swap — the most common Western-aesthetics error.", "പ്ലേറ്റോ/അരിസ്റ്റോട്ടിൽ മാറ്റം."), fix: L("Plato = copy of copy, exile the poet. Aristotle = mimesis + catharsis, keep the poet.", "പ്ലേറ്റോ കവിയെ നാടുകടത്തുന്നു. അരിസ്റ്റോട്ടിൽ നിലനിർത്തുന്നു.") }),
  Q({ id: "va-u5-05", paper: P, unitId: "va-u5", q: L("Kant’s judgement of beauty is famously", "കാന്റിന്റെ ഭംഗി വിധി"), options: [L("Interested and appetitive, like hunger", "വിശപ്പ് പോലെ താത്പര്യമുള്ളത്"), L("Disinterested — pleasure without a concept of use", "നിരപേക്ഷം — ഉപയോഗബോധമില്ലാത്ത സുഖം"), L("Identical to moral law", "ധാർമിക നിയമത്തിന് തുല്യം"), L("Only about the sublime storm", "സബ്ലൈം കൊടുങ്കാറ്റ് മാത്രം")], answer: 1, explain: L("Beauty: disinterested. Sublime: overwhelming magnitude/power. Two different Kantian aesthetics, both examinable.", "ഭംഗി നിരപേക്ഷം. സബ്ലൈം അതിശയിപ്പിക്കുന്ന വലുപ്പം. രണ്ടും ചോദിക്കാം."), trap: L("Sublime and beautiful as synonyms.", "സബ്ലൈമും ഭംഗിയും പര്യായം."), fix: L("Pretty flower → beauty. Alps/storm that almost crushes you → sublime.", "പൂവ് → ഭംഗി. ആൽപ്സ് → സബ്ലൈം.") }),
  Q({ id: "va-u5-06", paper: P, unitId: "va-u5", q: L("The rasa-sutra mechanism includes", "രസസൂത്രത്തിലെ യന്ത്രം"), options: [L("SMTP, IMAP, HTTP", "SMTP, IMAP, HTTP"), L("Vibhava, anubhava and vyabhicharibhava combining toward rasa", "വിഭാവ, അനുഭാവ, വ്യഭിചാരിഭാവം ചേർന്ന് രസം"), L("Only vanishing points", "വാനിഷിംഗ് പോയിന്റ് മാത്രം"), L("NAPCC eight missions", "NAPCC എട്ട് മിഷൻ")], answer: 1, explain: L("Determinants, consequents, transitory states; the durable sthayi-bhava is tasted as rasa.", "വിഭാവ, അനുഭാവ, വ്യഭിചാരി; സ്ഥായിഭാവം രസമായി ആസ്വദിക്കപ്പെടുന്നു."), trap: L("Memorising rasa names but not the production mechanism — JRF asks the engine.", "രസപ്പേര് മാത്രം — ജെആർഎഫ് എഞ്ചിൻ ചോദിക്കുന്നു."), fix: L("Names of 8 rasas AND the three-bhava engine. Both sides of the card.", "എട്ട് പേരും മൂന്ന് ഭാവ എഞ്ചിനും.") }),
  Q({ id: "va-u5-07", paper: P, unitId: "va-u5", q: L("A.K. Coomaraswamy’s writing typically treats Indian art as", "കുമാരസ്വാമിയുടെ എഴുത്ത് ഇന്ത്യൻ കലയെ"), options: [L("Mere ethnographic curiosity without metaphysics", "തത്ത്വചിന്തയില്ലാത്ത എത്നോഗ്രഫി"), L("A yoga of form grounded in traditional canons and meaning", "പാരമ്പര്യ കാനോനും അർഥവും ഉള്ള രൂപയോഗം"), L("Only Company-school watercolour", "കമ്പനി സ്കൂൾ വാട്ടർകളർ മാത്രം"), L("A branch of NAPCC", "NAPCC ശാഖ")], answer: 1, explain: L("With Havell and Abanindranath, Coomaraswamy philosophically armed the Bengal School / swadeshi reading of Indian art.", "ഹാവലിനും അബനീന്ദ്രനാഥിനുമൊപ്പം സ്വദേശി വായനയ്ക്ക് തത്ത്വചിന്ത നൽകി."), trap: L("Filing him only as ‘a Ceylon writer’ without the art-historical job.", "സിലോൺ എഴുത്തുകാരൻ മാത്രം."), fix: L("Unit V + VIII share him: aesthetics AND Bengal School ideology.", "യൂണിറ്റ് V+VIII. സൗന്ദര്യശാസ്ത്രവും ബംഗാൾ സ്കൂൾ ആശയവും.") }),
  Q({ id: "va-u5-08", paper: P, unitId: "va-u5", q: L("Vakrokti is associated with", "വക്രോക്തി ബന്ധപ്പെട്ടത്"), options: [L("Kuntaka — oblique / crooked expression as the mark of art", "കുന്തകൻ — വക്രഭാഷണം കലയുടെ അടയാളം"), L("Monet’s 1874 sunrise", "മോനെയുടെ 1874 സൂര്യോദയം"), L("Panofsky’s third level only", "പനോഫ്സ്കിയുടെ മൂന്നാം തലം മാത്രം"), L("ISA headquarters", "ISA ആസ്ഥാനം")], answer: 0, explain: L("Kuntaka’s Vakroktijivita: art lives by deflection from ordinary speech. Parallel to, not identical with, dhvani.", "വക്രോക്തിജീവിതം: സാധാരണ ഭാഷയിൽ നിന്നുള്ള വ്യതിയാനം. ധ്വനിയുടെ സമാന്തര സ്കൂൾ."), trap: L("All alamkara-dhvani-vakrokti dumped on Anandavardhana.", "എല്ലാം ആനന്ദവർധനനിൽ."), fix: L("One author one slogan. Don’t let the Sanskrit rhyme.", "ഒരു ഗ്രന്ഥകാരൻ ഒരു മുദ്രാവാക്യം.") }),

  Q({ id: "va-u6-01", paper: P, unitId: "va-u6", difficulty: "jrf", q: L("Les Demoiselles d’Avignon (1907) is a founding work of", "ലെ ഡെമോയ്സെൽ ദാവിനോൺ (1907) സ്ഥാപക കൃതി"), options: [L("Impressionism", "ഇംപ്രഷനിസം"), L("Cubism", "ക്യൂബിസം"), L("Pop art", "പോപ്പ് ആർട്ട്"), L("Ukiyo-e", "ഉക്യോ-ഇ")], answer: 1, explain: L("Picasso, 1907, proto-Cubist rupture (Iberian/African mask encounter). Impressionism is 1874 Monet; Pop is 1950s–60s.", "പിക്കാസോ 1907. ഇംപ്രഷൻ 1874. പോപ്പ് 1950–60."), trap: L("Any Picasso = Guernica 1937 only.", "പിക്കാസോ = ഗ്വെർണിക്ക മാത്രം."), fix: L("1907 Demoiselles Cubism. 1937 Guernica is later, political, still Picasso.", "1907 ക്യൂബിസം. 1937 ഗ്വെർണിക്ക പിന്നീട്.") }),
  Q({ id: "va-u6-02", paper: P, unitId: "va-u6", q: L("The 1874 Paris exhibition is conventionally the public birth of", "1874 പാരീസ് എക്സിബിഷൻ പൊതുജന ജനനം"), options: [L("Dada", "ഡാഡ"), L("Impressionism", "ഇംപ്രഷനിസം"), L("Minimalism", "മിനിമലിസം"), L("Bauhaus", "ബോഹൗസ്")], answer: 1, explain: L("Monet’s *Impression, Sunrise* gave the insult that became the name. Dada is 1916 Zurich.", "മോനെയുടെ ഇംപ്രഷൻ സൺറൈസ്. ഡാഡ 1916 സൂറിച്ച്."), trap: L("All French modernisms collapse to 1900.", "എല്ലാ ഫ്രഞ്ച് മോഡേണിസവും 1900."), fix: L("1874 Impression. 1905 Fauves. 1907 Cubism. 1916 Dada. 1924 Surrealism.", "ഈ അഞ്ച് വർഷം ജപിക്കുക.") }),
  Q({ id: "va-u6-03", paper: P, unitId: "va-u6", q: L("Dada is tied to", "ഡാഡ ബന്ധപ്പെട്ടത്"), options: [L("Cabaret Voltaire, Zurich, c. 1916 — anti-art, chance, ready-made", "കബറേ വോൾട്ടയർ, സൂറിച്ച്, c. 1916 — ആന്റി-ആർട്ട്, ചാൻസ്, റെഡിമെയ്ഡ്"), L("Medici Florence 1430", "മെഡിചി ഫ്ലോറൻസ് 1430"), L("Ajanta Cave 1", "അജന്ത ഗുഹ 1"), L("NID Ahmedabad 1961 only", "NID അഹമ്മദാബാദ് 1961 മാത്രം")], answer: 0, explain: L("World War I shock. Duchamp’s Fountain (1917) is the ready-made emblem, New York/Paris wing.", "ഒന്നാം ലോകയുദ്ധ ഷോക്ക്. ഡുഷാമ്പിന്റെ ഫൗണ്ടൻ 1917."), trap: L("Surrealism and Dada as one blob.", "സർറിയലിസവും ഡാഡയും ഒരു കുഴമ്പ്."), fix: L("Dada first (destruct). Surrealism after (Breton 1924 manifesto, dream).", "ഡാഡ ആദ്യം (ഭഞ്ജനം). സർറിയൽ പിന്നെ (സ്വപ്നം).") }),
  Q({ id: "va-u6-04", paper: P, unitId: "va-u6", q: L("High Renaissance in Italy is conventionally the triad", "ഇറ്റാലിയൻ ഹൈ റിനൈസൻസ് ത്രയം"), options: [L("Monet, Renoir, Degas", "മോനെ, റെനോവാ, ഡെഗാ"), L("Leonardo, Michelangelo, Raphael", "ലിയോനാർഡോ, മൈക്കൽആഞ്ചലോ, റാഫേൽ"), L("Souza, Raza, Husain", "സൂസ, റസ, ഹുസൈൻ"), L("Hokusai, Hiroshige, Utamaro", "ഹോകുസായി, ഹിരോഷിഗെ, ഉതമാരോ")], answer: 1, explain: L("c. 1495–1520 Florence/Rome/some Milan. Venice (Titian) is the colour parallel, sometimes asked separately.", "c. 1495–1520. വെനീസ് (ടിഷ്യൻ) വേറെ കളർ ശാഖ."), trap: L("Renaissance = any old master.", "റിനൈസൻസ് = ഏത് ഓൾഡ് മാസ്റ്ററും."), fix: L("Early = Giotto/Masaccio. High = the triad. Late/Mannerist = Pontormo, El Greco stretch.", "ആദ്യം ഗിയോട്ടോ/മസാച്ചോ. ഹൈ ത്രയം. മാനറിസ്റ്റ് പിന്നെ.") }),
  Q({ id: "va-u6-05", paper: P, unitId: "va-u6", q: L("Caravaggio is the textbook name for", "കാരവാജിയോ പാഠപുസ്തക പേര്"), options: [L("Tenebrism / dramatic chiaroscuro in Baroque painting", "ബറോക്ക് ചിത്രത്തിലെ ടെനെബ്രിസം / നാടകീയ കിയാരോസ്കുറോ"), L("Impressionist broken colour", "ഇംപ്രഷനിസ്റ്റ് ബ്രോക്കൺ കളർ"), L("Minimal fluorescent sculptures", "മിനിമൽ ഫ്ലൂറസന്റ് ശില്പം"), L("Pahari Basohli miniature", "പഹാഡി ബസോഹ്ലി മിനിയേച്ചർ")], answer: 0, explain: L("Light stabs out of dark. Bernini does the sculptural Baroque; Rubens the Flemish painterly Baroque.", "ഇരുട്ടിൽ നിന്ന് വെളിച്ചം. ബെർനിനി ശില്പ ബറോക്ക്; റൂബൻസ് ഫ്ലെമിഷ്."), trap: L("Chiaroscuro invented in the 20th century.", "കിയാരോസ്കുറോ 20-ാം നൂറ്റാണ്ട്."), fix: L("Baroque painting keyword = tenebrism/Caravaggio. Sculpture keyword = Bernini.", "ചിത്രം കാരവാജിയോ. ശില്പം ബെർനിനി.") }),
  Q({ id: "va-u6-06", paper: P, unitId: "va-u6", q: L("Abstract Expressionism is centred on", "അബ്സ്ട്രാക്റ്റ് എക്സ്പ്രഷനിസത്തിന്റെ കേന്ദ്രം"), options: [L("1940s–50s New York — Pollock, Rothko, de Kooning", "1940–50കൾ ന്യൂയോർക്ക് — പോലക്, റോത്കോ, ഡി കൂണിങ്"), L("1320 Siena", "1320 സിയെന"), L("PAG Bombay 1947 exclusively", "PAG ബോംബെ 1947 മാത്രം"), L("Qin terracotta pits", "ക്വിൻ ടെറാക്കോട്ട")], answer: 0, explain: L("First time the ‘centre’ of Western painting is said to leave Paris. Action painting vs colour field are internal splits.", "പാരീസ് വിട്ട് ന്യൂയോർക്ക്. ആക്ഷൻ vs കളർ ഫീൽഡ്."), trap: L("Expressionism = German 1910s Die Brücke, so people pick the wrong decade.", "ജർമ്മൻ എക്സ്പ്രഷനിസം 1910 — വേറെ ദശകം."), fix: L("German Expressionism c. 1905–20. Abstract Expressionism = NY after WWII.", "ജർമ്മൻ 1905–20. അബ്സ്ട്രാക്റ്റ് എക്സ്പ്രഷൻ = യുദ്ധാനന്തര NY.") }),
  Q({ id: "va-u6-07", paper: P, unitId: "va-u6", q: L("Pop art typically", "പോപ്പ് ആർട്ട് സാധാരണ"), options: [L("Refuses mass-culture images", "മാസ്-കൾച്ചർ ചിത്രങ്ങൾ നിരാകരിക്കുന്നു"), L("Uses ads, comics, celebrities — Warhol, Lichtenstein", "പരസ്യം, കോമിക്, സെലിബ്രിറ്റി — വാർഹോൾ, ലിക്റ്റൻസ്റ്റൈൻ"), L("Is identical to Ajanta jataka", "അജന്ത ജാതകത്തിന് തുല്യം"), L("Is a Vedic pramana", "വൈദിക പ്രമാണം")], answer: 1, explain: L("1950s Britain / 1960s USA. Opposite of Abstract Expressionist angst — cool, serial, commercial.", "അബ്സ്ട്രാക്റ്റ് എക്സ്പ്രഷൻ വേദനയുടെ വിപരീതം — തണുത്ത, സീരിയൽ, വാണിജ്യ."), trap: L("Pop = popular = folk Warli.", "പോപ്പ് = നാടൻ."), fix: L("Pop = mass media West. Folk = Unit X India. Don’t translate the word ‘popular’.", "പോപ്പ് = പാശ്ചാത്യ മാസ് മീഡിയ. നാടൻ = യൂണിറ്റ് X.") }),
  Q({ id: "va-u6-08", paper: P, unitId: "va-u6", q: L("Postmodern practices named in the syllabus include", "സിലബസിലെ പോസ്റ്റ്‌മോഡേൺ പ്രാക്ടീസ്"), options: [L("Only Lascaux bison", "ലാസ്കോ കാട്ടുപോത്ത് മാത്രം"), L("Minimal and conceptual art, Fluxus, Arte Povera, land art, performance, installation, feminist art", "മിനിമൽ, കൺസെപ്ച്വൽ, ഫ്ലക്സസ്, ആർട്ടെ പോവേര, ലാൻഡ് ആർട്ട്, പെർഫോമൻസ്, ഇൻസ്റ്റലേഷൻ, ഫെമിനിസ്റ്റ് ആർട്ട്"), L("Mauryan polish exclusively", "മൗര്യ പോളിഷ് മാത്രം"), L("SWAYAM courses", "SWAYAM കോഴ്സുകൾ")], answer: 1, explain: L("The official Visual Art syllabus literally lists these. Don’t treat postmodern as ‘anything after 2000’.", "ഔദ്യോഗിക സിലബസ് ഈ ലിസ്റ്റ് അച്ചടിക്കുന്നു. പോസ്റ്റ്‌മോഡേൺ = 2000-ന് ശേഷം എന്നല്ല."), trap: L("Postmodern = chaos, so no MCQ can be answered.", "പോസ്റ്റ്‌മോഡേൺ = കുഴപ്പം, എംസിക്യു ഉത്തരമില്ല."), fix: L("Learn the syllabus list as a chant, same as rasa names.", "സിലബസ് ലിസ്റ്റ് രസപ്പേരുകൾ പോലെ ജപിക്കുക.") }),

  Q({ id: "va-u7-01", paper: P, unitId: "va-u7", difficulty: "jrf", q: L("Gandhara Buddha images are typically", "ഗന്ധാര ബുദ്ധ പ്രതിമകൾ സാധാരണ"), options: [L("Spotted red sandstone, indigenous fullness (Mathura type)", "ചുവന്ന മണൽക്കല്ല്, തദ്ദേശീയ പൂർണത (മഥുര)"), L("Grey schist, Hellenistic drapery and wavy hair", "ചാര ഷിസ്റ്റ്, ഹെല്ലനിസ്റ്റിക് വസ്ത്രം, തിരയിട്ട മുടി"), L("Chola lost-wax portable bronzes only", "ചോള ലോസ്റ്റ്-വാക്സ് മാത്രം"), L("Warli white rice paste", "വാർലി അരി പേസ്റ്റ്")], answer: 1, explain: L("Two Kushana Buddha factories: Gandhara (Greek memory) and Mathura (red sandstone, fuller body). Gupta Sarnath later refines.", "കുഷാണയിൽ രണ്ട് ഫാക്ടറി: ഗന്ധാര, മഥുര. ഗുപ്ത സാരനാഥ് പിന്നെ."), trap: L("All Buddhas = Gandhara because textbooks show that photo first.", "പാഠപുസ്തക ഫോട്ടോ ഗന്ധാര."), fix: L("Grey-Greek-Gandhara. Red-round-Mathura. Cream-classical-Sarnath Gupta.", "ഗ്രേ-ഗ്രീക്ക്-ഗന്ധാര. റെഡ്-റൗണ്ട്-മഥുര. ക്രീം-സാരനാഥ്.") }),
  Q({ id: "va-u7-02", paper: P, unitId: "va-u7", q: L("The Lion Capital of Sarnath belongs to", "സാരനാഥ് സിംഹമുദ്ര"), options: [L("Chola 11th century", "ചോള 11-ാം നൂറ്റാണ്ട്"), L("Mauryan, Ashokan", "മൗര്യ, അശോകൻ"), L("Mughal Jahangir atelier", "മുഗൾ ജഹാംഗീർ അറ്റിലിയെ"), L("PAG 1947", "PAG 1947")], answer: 1, explain: L("Polished sandstone, four lions, inverted lotus — India’s national emblem source. Mauryan polish is a dating clue.", "മിനുസമുള്ള മണൽക്കല്ല്, നാല് സിംഹം. മൗര്യ പോളിഷ് ഡേറ്റിംഗ് ക്ലൂ."), trap: L("Sarnath → only Gupta Buddha.", "സാരനാഥ് → ഗുപ്ത ബുദ്ധ മാത്രം."), fix: L("Sarnath has two hits: Ashokan capital AND Gupta standing Buddha. Different centuries.", "സാരനാഥിൽ രണ്ട് ഹിറ്റ്: അശോകൻ മുദ്ര, ഗുപ്ത ബുദ്ധ.") }),
  Q({ id: "va-u7-03", paper: P, unitId: "va-u7", q: L("Nagara, Dravida and Vesara are", "നാഗര, ദ്രാവിഡ, വേസര"), options: [L("Print families", "പ്രിന്റ് കുടുംബങ്ങൾ"), L("Temple-language classifications of Indian architecture", "ഇന്ത്യൻ വാസ്തുവിദ്യയിലെ ക്ഷേത്രഭാഷാ വർഗ്ഗീകരണം"), L("Rasa names", "രസപ്പേരുകൾ"), L("PAG members", "PAG അംഗങ്ങൾ")], answer: 1, explain: L("Nagara = north, shikhara/rekha-deul. Dravida = south, vimana storeys. Vesara = Deccan hybrid (Chalukya etc.).", "നാഗര ഉത്തരം ശിഖര. ദ്രാവിഡ ദക്ഷിണം വിമാനം. വേസര ദക്കൺ."), trap: L("Vesara forgotten; only two styles remembered from school.", "സ്കൂളിൽ രണ്ട് ശൈലി മാത്രം — വേസര മറന്നു."), fix: L("Three labels on the map of India: N / S / Deccan.", "ഭൂപടത്തിൽ മൂന്ന് ലേബൽ: വടക്ക് / തെക്ക് / ദക്കൺ.") }),
  Q({ id: "va-u7-04", paper: P, unitId: "va-u7", q: L("Ajanta’s celebrated murals are especially associated with", "അജന്തയുടെ പ്രശസ്ത മ്യൂറലുകൾ പ്രത്യേകം"), options: [L("Vakataka patronage, roughly 5th century CE in the later caves", "വാകാടക രക്ഷാധികാരം, പിൽക്കാല ഗുഹകളിൽ ഏകദേശം 5-ാം നൂ. സി.ഇ."), L("Shah Jahan’s marble inlay", "ഷാജഹാന്റെ മാർബിൾ ഇൻലേ"), L("Company school 1850s", "കമ്പനി സ്കൂൾ 1850കൾ"), L("Bauhaus 1919", "ബോഹൗസ് 1919")], answer: 0, explain: L("Earlier Satavahana phase exists; the painterly peak is Vakataka (Harishena), Cave 1 and 17 often cited. Not Mughal, not colonial.", "മുമ്പ് സാതവാഹന ഘട്ടം; ചിത്രശ്രേഷ്ഠം വാകാടക (ഹരിഷേണ)."), trap: L("Ajanta = Gupta automatically.", "അജന്ത = ഗുപ്ത യാന്ത്രികമായി."), fix: L("Political frame: Vakataka Deccan, Gupta-period contemporaneity — allied, not identical.", "വാകാടക ദക്കൺ, ഗുപ്ത കാലഘട്ട സമകാലികം — ഒന്നല്ല.") }),
  Q({ id: "va-u7-05", paper: P, unitId: "va-u7", q: L("Jahangir’s atelier is famed for", "ജഹാംഗീറിന്റെ അറ്റിലിയെ പ്രശസ്തം"), options: [L("Naturalistic portrait, flora-fauna (Mansur), album pages", "സ്വാഭാവിക പോർട്രെയ്റ്റ്, സസ്യ-മൃഗം (മൻസൂർ), ആൽബം"), L("Only huge historical battle screens like Akbar’s earliest Hamzanama energy", "അക്ബറിന്റെ ആദ്യ ഹംസാനാമ യുദ്ധതിരശ്ശീല മാത്രം"), L("Cubist collage", "ക്യൂബിസ്റ്റ് കൊളാഷ്"), L("Warli triangles", "വാർലി ത്രികോണം")], answer: 0, explain: L("Akbar: synthesis, dynamism, Hamzanama. Jahangir: observation, portrait, natural history. Shah Jahan: polish, architecture-adjacent refinement.", "അക്ബർ ഊർജം. ജഹാംഗീർ നിരീക്ഷണം. ഷാജഹാൻ മിനുസം."), trap: L("All Mughal painting = Akbar.", "എല്ലാ മുഗൾ ചിത്രവും അക്ബർ."), fix: L("Emperor-trait triad. It wins matching questions.", "ചക്രവർത്തി-ലക്ഷണ ത്രയം. മാച്ചിംഗ് ജയിക്കും.") }),
  Q({ id: "va-u7-06", paper: P, unitId: "va-u7", q: L("Bani Thani is associated with", "ബനി ഠനി ബന്ധപ്പെട്ടത്"), options: [L("Kishangarh, often linked to Nihal Chand", "കിഷൻഗഢ്, പലപ്പോഴും നിഹാൽ ചന്ദ്"), L("Basohli’s hot mineral yellow only", "ബസോഹ്ലിയുടെ കടും മഞ്ഞ മാത്രം"), L("PAG Bombay", "PAG ബോംബെ"), L("Sigiriya maidens", "സിഗിരിയ നായികമാർ")], answer: 0, explain: L("Arched eye, elongated form, Radha-ideal. Rajasthani school, not Pahari Basohli (which has its own intense palette and square format).", "വളഞ്ഞ കണ്ണ്, നീണ്ട രൂപം, രാധാ-ആദർശം. രാജസ്ഥാനി, പഹാഡി ബസോഹ്ലി അല്ല."), trap: L("All lyrical heroines = Kangra.", "എല്ലാ നായികമാരും കാംഗ്ര."), fix: L("Kishangarh-Bani Thani. Kangra-Nainsukh/Gita Govinda softness. Basohli-intense, early Pahari.", "കിഷൻഗഢ്-ബനി ഠനി. കാംഗ്ര-മൃദുത്വം. ബസോഹ്ലി-തീവ്രത.") }),
  Q({ id: "va-u7-07", paper: P, unitId: "va-u7", q: L("The Kailasa temple at Ellora is a Rashtrakuta", "എല്ലോറയിലെ കൈലാസ ക്ഷേത്രം രാഷ്ട്രകൂട"), options: [L("Rock-cut monolithic excavation — subtractive architecture", "പാറയിൽ കൊത്തിയ മോണോലിത്തിക് ഖനനം — സബ്ട്രാക്റ്റീവ് വാസ്തു"), L("Mughal marble tomb", "മുഗൾ മാർബിൾ ഖബർ"), L("British art-school studio", "ബ്രിട്ടീഷ് ആർട്ട് സ്കൂൾ സ്റ്റുഡിയോ"), L("Ukiyo-e publisher’s shop", "ഉക്യോ-ഇ കട")], answer: 0, explain: L("Krishna I period traditionally; the mountain is the shikhara. Carving as architecture — Unit III verb in Unit VII monument.", "കൃഷ്ണൻ I. പർവ്വതം തന്നെ ശിഖരം. യൂണിറ്റ് III ക്രിയ യൂണിറ്റ് VII സ്മാരകത്തിൽ."), trap: L("Ellora = only Buddhist viharas, or only Ajanta’s twin painting site.", "എല്ലോറ = ബൗദ്ധ വിഹാരം മാത്രം / അജന്തയുടെ ജോടി ചിത്രസ്ഥലം."), fix: L("Ajanta ≈ painting+vihara. Ellora ≈ three religions in rock, Kailasa Hindu peak.", "അജന്ത ചിത്രം. എല്ലോറ മൂന്ന് മതം, കൈലാസ ഹൈന്ദവ ശൃംഗം.") }),
  Q({ id: "va-u7-08", paper: P, unitId: "va-u7", q: L("Company painting refers to", "കമ്പനി ചിത്രം"), options: [L("Works made for British East India Company patrons, hybrid Indian-European visuality", "ബ്രിട്ടീഷ് ഈസ്റ്റ് ഇന്ത്യാ കമ്പനി രക്ഷാധികാരികൾക്ക്, ഇന്ത്യൻ-യൂറോപ്യൻ ഹൈബ്രിഡ്"), L("PAG oil in 1947 only", "1947 PAG ഓയിൽ മാത്രം"), L("Chola bronzes", "ചോള വെങ്കലം"), L("Thangka commissions in Lhasa only", "ലാസയിലെ തങ്ക മാത്രം")], answer: 0, explain: L("Late 18th–19th c. Indian artists painting trades, castes, flora, architecture in a European-watercolour gaze — bridge into Unit VIII.", "18–19 നൂ. വ്യാപാരം, ജാതി, സസ്യം — യൂറോപ്യൻ വാട്ടർകളർ നോട്ടം. യൂണിറ്റ് VIII-ലേക്കുള്ള പാലം."), trap: L("Company = contemporary corporate art.", "കമ്പനി = ഇന്നത്തെ കോർപ്പറേറ്റ് ആർട്ട്."), fix: L("Company school = colonial patron. Bengal School = swadeshi answer to that gaze.", "കമ്പനി = കൊളോണിയൽ രക്ഷാധികാരി. ബംഗാൾ സ്കൂൾ = സ്വദേശി മറുപടി.") }),

  Q({ id: "va-u8-01", paper: P, unitId: "va-u8", difficulty: "jrf", q: L("The Progressive Artists’ Group was formed in", "പ്രോഗ്രസീവ് ആർട്ടിസ്റ്റ്സ് ഗ്രൂപ്പ് രൂപം"), options: [L("Calcutta, 1943", "കൽക്കട്ട, 1943"), L("Bombay, 1947", "ബോംബെ, 1947"), L("Chennai, 1966", "ചെന്നൈ, 1966"), L("Baroda, 1950 as NID", "ബറോഡ, 1950 NID ആയി")], answer: 1, explain: L("PAG Bombay 1947: Souza, Raza, Husain, Ara, Bakre, Gade. Calcutta Group is a different 1940s collective. Cholamandal is 1966.", "PAG ബോംബെ 1947. കൽക്കട്ട ഗ്രൂപ്പ് വേറെ. ചോഴമണ്ഡലം 1966."), trap: L("Independence-year + Bengal renaissance = Calcutta 1947.", "സ്വാതന്ത്ര്യം + ബംഗാൾ = കൽക്കട്ട 1947."), fix: L("Three dates: Calcutta Group ~1943, PAG 1947 Bombay, Cholamandal 1966.", "മൂന്ന് തീയതി മതി.") }),
  Q({ id: "va-u8-02", paper: P, unitId: "va-u8", q: L("Abanindranath Tagore’s Bharat Mata is a key image of", "അബനീന്ദ്രനാഥ് താഗോറിന്റെ ഭാരതമാതാ"), options: [L("Pop art", "പോപ്പ് ആർട്ട്"), L("Bengal School / swadeshi wash painting", "ബംഗാൾ സ്കൂൾ / സ്വദേശി വാഷ്"), L("Chola bronze", "ചോള വെങ്കലം"), L("Ukiyo-e actor print", "ഉക്യോ-ഇ നടൻ പ്രിന്റ്")], answer: 1, explain: L("Wash technique, Ajanta-Mughal memory, anti-academic. Havell and Coomaraswamy are the ideological partners.", "വാഷ്, അജന്ത-മുഗൾ ഓർമ്മ, അക്കാദമിക് വിരുദ്ധം."), trap: L("Any Tagore = Rabindranath’s paintings only.", "താഗോർ = രബീന്ദ്രനാഥ് ചിത്രം മാത്രം."), fix: L("Abanindranath = Bengal School founder-figure. Rabindranath = later, more private, less revivalist.", "അബനീന്ദ്രൻ ബംഗാൾ സ്കൂൾ. രബീന്ദ്രൻ പിന്നീട്, കൂടുതൽ സ്വകാര്യം.") }),
  Q({ id: "va-u8-03", paper: P, unitId: "va-u8", q: L("Raja Ravi Varma is crucial because he", "രവി വർമ്മ നിർണായകം — അദ്ദേഹം"), options: [L("Rejected oil and oleographs", "ഓയിലും ഒലിയോഗ്രാഫും നിരാകരിച്ചു"), L("Used academic oil and oleographs to mass-circulate Hindu iconography", "അക്കാദമിക് ഓയിലും ഒലിയോഗ്രാഫും കൊണ്ട് ഹൈന്ദവ ഐക്കണോഗ്രഫി ബഹുജനമാക്കി"), L("Founded Cholamandal", "ചോഴമണ്ഡലം സ്ഥാപിച്ചു"), L("Painted only Warli mud walls", "വാർലി ചെളിച്ചുവർ മാത്രം")], answer: 1, explain: L("The Bengal School defined itself partly against his ‘theatrical’ oil. Both are on the syllabus; don’t pick a side in the exam, pick the fact.", "ബംഗാൾ സ്കൂൾ അദ്ദേഹത്തിന്റെ ഓയിലിനെതിരെ നിർവചിച്ചു. പരീക്ഷയിൽ വസ്തുത എടുക്കുക, പക്ഷം അല്ല."), trap: L("Modernist disdain → ‘he is not important’.", "മോഡേണിസ്റ്റ് നിന്ദ → പ്രധാനമല്ല."), fix: L("Ravi Varma = oil + oleograph + Puranic body. Bengal School = wash + swadeshi. Two facts, not a moral.", "രണ്ട് വസ്തുത, ഒരു ധാർമികത അല്ല.") }),
  Q({ id: "va-u8-04", paper: P, unitId: "va-u8", q: L("Santiniketan’s modern triad is", "ശാന്തിനികേതന്റെ ആധുനിക ത്രയം"), options: [L("Nandalal Bose, Benodebehari Mukherjee, Ramkinkar Baij", "നന്ദലാൽ ബോസ്, ബിനോദ്‌ബിഹാരി മുഖർജി, രാംകിങ്കർ ബൈജ്"), L("Souza, Raza, Husain only", "സൂസ, റസ, ഹുസൈൻ മാത്രം"), L("Monet, Sisley, Pissarro", "മോനെ, സിസ്ലി, പിസാറോ"), L("Havell, Kipling, Curzon", "ഹാവൽ, കിപ്ലിങ്, കർസൺ")], answer: 0, explain: L("Nandalal (pedagogy, Haripura posters), Benodebehari (Hindi Bhavan mural, later blind work), Ramkinkar (outdoor modernist sculpture). Kala Bhavana.", "നന്ദലാൽ പെഡഗോജി, ബിനോദ്‌ബിഹാരി മ്യൂറൽ, രാംകിങ്കർ ഔട്ട്ഡോർ ശില്പം."), trap: L("Santiniketan = only Rabindranath.", "ശാന്തിനികേതൻ = രബീന്ദ്രൻ മാത്രം."), fix: L("Tagore founded the ethos; the triad taught the craft. Both sentences are true.", "താഗോർ ആശയം; ത്രയം കരകൗശലം. രണ്ട് വാചകവും ശരി.") }),
  Q({ id: "va-u8-05", paper: P, unitId: "va-u8", q: L("Cholamandal Artists’ Village (1966) is linked to", "ചോഴമണ്ഡലം (1966) ബന്ധപ്പെട്ടത്"), options: [L("K.C.S. Paniker, near Chennai", "കെ.സി.എസ്. പാനിക്കർ, ചെന്നൈയ്ക്കടുത്ത്"), L("Mansur at Jahangir’s court", "ജഹാംഗീർ ദർബാറിലെ മൻസൂർ"), L("The Qin terracotta army", "ക്വിൻ ടെറാക്കോട്ട സേന"), L("Cabaret Voltaire", "കബറേ വോൾട്ടയർ")], answer: 0, explain: L("Living-working village, Madras School modernism, tantric/script signs in Paniker. A South Indian counterweight to Bombay PAG in MCQs.", "ജീവിത-സ്റ്റുഡിയോ ഗ്രാമം, മദ്രാസ് മോഡേണിസം. PAG-യുടെ ദക്ഷിണ ഭാരസമത്വം."), trap: L("Any ‘village of artists’ = Santiniketan.", "കലാകാര ഗ്രാമം = ശാന്തിനികേതൻ."), fix: L("Santiniketan = 1920s Bengal university. Cholamandal = 1966 Madras village. Different model.", "ശാന്തിനികേതൻ സർവകലാശാല. ചോഴമണ്ഡലം ഗ്രാമം.") }),
  Q({ id: "va-u8-06", paper: P, unitId: "va-u8", predicted: true, q: L("The Kochi-Muziris Biennale began in", "കൊച്ചി-മുസിരിസ് ബിനാലെ തുടക്കം"), options: [L("1947", "1947"), L("1966", "1966"), L("2012", "2012"), L("1857", "1857")], answer: 2, explain: L("First edition 2012, Kerala — contemporary installation, new media, curatorial turn. Prime Unit VIII current-cycle fact.", "ആദ്യ എഡിഷൻ 2012. യൂണിറ്റ് VIII കറന്റ്-സൈക്കിൾ വസ്തുത."), trap: L("Biennale feels ‘European 19th century’ so people pick 1857.", "ബിനാലെ യൂറോപ്യൻ 19-ാം നൂറ്റാണ്ട് — 1857."), fix: L("Venice Biennale 1895 (world). Kochi 2012 (India’s landmark). Two dates.", "വെനീസ് 1895. കൊച്ചി 2012.") }),
  Q({ id: "va-u8-07", paper: P, unitId: "va-u8", q: L("Amrita Sher-Gil is best tagged as", "അമൃത ഷെർഗിൽ"), options: [L("Paris-trained modernist who turned to Indian subjects (e.g. Three Girls)", "പാരീസ് പഠിച്ച മോഡേണിസ്റ്റ്, ഇന്ത്യൻ വിഷയത്തിലേക്ക് (ത്രീ ഗേൾസ്)"), L("A Chola bronze caster", "ചോള വെങ്കല കാസ്റ്റർ"), L("Founder of PAG in 1947", "1947 PAG സ്ഥാപക"), L("An ukiyo-e carver", "ഉക്യോ-ഇ കൊത്തുപണിക്കാരി")], answer: 0, explain: L("Hungarian-Indian, died 1941 — before PAG. A bridge between European modernism and Indian subjecthood, often compared with (not identical to) the Bengal School.", "1941-ൽ മരണം — PAG-യ്ക്ക് മുമ്പ്. യൂറോപ്യൻ മോഡേണിസവും ഇന്ത്യൻ വിഷയവും."), trap: L("Woman painter → Bengal School wash automatically.", "സ്ത്രീ ചിത്രകാരി → ബംഗാൾ വാഷ്."), fix: L("Sher-Gil = oil, Paris, 1930s. Bengal wash = Abanindranath line. Different tools.", "ഷെർഗിൽ ഓയിൽ/പാരീസ്. ബംഗാൾ വാഷ് അബനീന്ദ്രൻ.") }),
  Q({ id: "va-u8-08", paper: P, unitId: "va-u8", q: L("Colonial art schools in India were founded notably at", "കൊളോണിയൽ ആർട്ട് സ്കൂളുകൾ"), options: [L("Madras, Calcutta, Bombay (and Lahore)", "മദ്രാസ്, കൽക്കട്ട, ബോംബെ (ലാഹോർ)"), L("Only Santiniketan in 1921 as the first ever", "1921 ശാന്തിനികേതൻ മാത്രം ആദ്യം"), L("Only NID in 1961 as the first ever", "1961 NID മാത്രം ആദ്യം"), L("Takshashila under Ashoka", "അശോകന്റെ കീഴിൽ തക്ഷശില")], answer: 0, explain: L("19th-c British academic pedagogy. Santiniketan and later NID (1961, design) are answers to, not the origin of, that system.", "19-ാം നൂ. ബ്രിട്ടീഷ് അക്കാദമിക് പെഡഗോജി. ശാന്തിനികേതനും NID-യും മറുപടികൾ, ഉത്ഭവമല്ല."), trap: L("First art school = Santiniketan, because it is beloved.", "ഇഷ്ടമായതിനാൽ ശാന്തിനികേതൻ ആദ്യ സ്കൂൾ."), fix: L("Colonial four: Madras/Calcutta/Bombay/Lahore. Anti-colonial lab: Santiniketan. Design modernity: NID.", "കൊളോണിയൽ നാല്. സ്വദേശി ലാബ് ശാന്തിനികേതൻ. ഡിസൈൻ NID.") }),

  Q({ id: "va-u9-01", paper: P, unitId: "va-u9", q: L("A ziggurat is", "സിഗുറാറ്റ്"), options: [L("A Mesopotamian stepped temple platform, not an Egyptian tomb pyramid", "മെസൊപ്പൊട്ടേമിയൻ പടിക്കെട്ടുള്ള ക്ഷേത്ര പ്ലാറ്റ്ഫോം — ഈജിപ്ഷ്യൻ ശവകുടീര പിരമിഡല്ല"), L("A Japanese haniwa figure", "ജാപ്പനീസ് ഹനിവ"), L("A Kerala mural pigment", "കേരള മ്യൂറൽ പിഗ്മെന്റ്"), L("A type of wasli", "വാസ്ലി")], answer: 0, explain: L("Sumerian/Babylonian sacred mountain of brick. Egypt’s pyramid is a tomb with different theology. NTA likes this distinction.", "സുമേർ/ബാബിലോൺ ഇഷ്ടികാ പർവ്വതം. ഈജിപ്ത് പിരമിഡ് ശവകുടീരം."), trap: L("All stepped sacred piles = pyramid.", "എല്ലാ പടിക്കെട്ട് കുന്നും പിരമിഡ്."), fix: L("Ziggurat = Mesopotamia temple. Pyramid = Egypt tomb. Stupa = Buddhist relic mound.", "സിഗുറാറ്റ് ക്ഷേത്രം. പിരമിഡ് ശവകുടീരം. സ്തൂപം ധാതു.") }),
  Q({ id: "va-u9-02", paper: P, unitId: "va-u9", difficulty: "jrf", q: L("Angkor Wat versus Borobudur: the fair contrast is", "അങ്കോർ വാട്ട് vs ബോറോബുദൂർ"), options: [L("Both are identical Chola shore temples in Tamil Nadu", "രണ്ടും തമിഴ്നാട്ടിലെ ഒരേ ചോള തീരക്ഷേത്രം"), L("Angkor Wat is a Khmer Hindu (Vishnu) temple-mountain; Borobudur is a Javanese Buddhist mandala-mountain", "അങ്കോർ വാട്ട് ഖമർ ഹൈന്ദവ (വിഷ്ണു) ക്ഷേത്ര-പർവ്വതം; ബോറോബുദൂർ ജാവനീസ് ബൗദ്ധ മണ്ഡല-പർവ്വതം"), L("Both are ukiyo-e series", "രണ്ടും ഉക്യോ-ഇ"), L("Both are Mauryan lion capitals", "രണ്ടും മൗര്യ സിംഹമുദ്ര")], answer: 1, explain: L("Indian forms travel and localise — the point of Unit IX. Don’t baptise every SE Asian monument ‘Buddhist stupa’.", "ഇന്ത്യൻ രൂപം യാത്ര ചെയ്ത് തദ്ദേശീയമാകുന്നു. എല്ലാം സ്തൂപമാക്കരുത്."), trap: L("South-East Asia = Buddhism only.", "തെക്കുകിഴക്കൻ ഏഷ്യ = ബുദ്ധമതം മാത്രം."), fix: L("Angkor-Vishnu-Khmer. Borobudur-Buddha-Java. Two sentences.", "അങ്കോർ-വിഷ്ണു-ഖമർ. ബോറോബുദൂർ-ബുദ്ധ-ജാവ.") }),
  Q({ id: "va-u9-03", paper: P, unitId: "va-u9", q: L("Ukiyo-e is", "ഉക്യോ-ഇ"), options: [L("Edo-period ‘pictures of the floating world’ — woodblock, actors, beauties, landscapes", "എഡോ ‘ഒഴുകുന്ന ലോകത്തിന്റെ ചിത്രങ്ങൾ’ — വുഡ്ബ്ലോക്ക്, നടൻ, സുന്ദരി, ഭൂപ്രകൃതി"), L("A Gupta ceiling fresco only", "ഗുപ്ത സീലിംഗ് ഫ്രെസ്കോ മാത്രം"), L("A pramana", "ഒരു പ്രമാണം"), L("NAPCC’s ninth mission", "NAPCC ഒമ്പതാം മിഷൻ")], answer: 0, explain: L("Hokusai, Hiroshige, Utamaro. Relief woodblock, multiple colour blocks — Unit III technique in Unit IX culture.", "ഹോകുസായി, ഹിരോഷിഗെ, ഉതമാരോ. റിലീഫ് വുഡ്ബ്ലോക്ക് — യൂണിറ്റ് III സാങ്കേതികത യൂണിറ്റ് IX-ൽ."), trap: L("Japanese painting = only Zen ink landscape.", "ജാപ്പനീസ് ചിത്രം = സെൻ മഷി മാത്രം."), fix: L("Song/Yuan China = literati landscape. Edo Japan popular prints = ukiyo-e. Different class, different medium.", "ചൈന ലിറ്ററാറ്റി ലാൻഡ്സ്കേപ്പ്. ജപ്പാൻ ജനപ്രിയ പ്രിന്റ്.") }),
  Q({ id: "va-u9-04", paper: P, unitId: "va-u9", q: L("The terracotta army belongs to", "ടെറാക്കോട്ട സേന"), options: [L("Qin China, tomb of the First Emperor", "ക്വിൻ ചൈന, ഒന്നാം ചക്രവർത്തിയുടെ ശവകുടീരം"), L("Mauryan Pataliputra only", "മൗര്യ പാടലീപുത്രം മാത്രം"), L("Cholamandal 1966", "ചോഴമണ്ഡലം 1966"), L("Sigiriya rock", "സിഗിരിയ പാറ")], answer: 0, explain: L("Life-size fired clay soldiers, horses — funerary mass production. Not Indus terracotta toys, not Mauryan polish.", "ജീവൻ-വലുപ്പമുള്ള ചുട്ട കളിമൺ സൈനികർ. സിന്ധു കളിപ്പാട്ടമല്ല."), trap: L("Terracotta → always Indus or folk India.", "ടെറാക്കോട്ട → സിന്ധു/നാടൻ ഇന്ത്യ മാത്രം."), fix: L("Material doesn’t fix civilisation. Ask scale and tomb context.", "മെറ്റീരിയൽ നാഗരികത നിശ്ചയിക്കില്ല. സ്കെയിലും ശവകുടീരവും ചോദിക്കുക.") }),
  Q({ id: "va-u9-05", paper: P, unitId: "va-u9", q: L("Sigiriya is famous for", "സിഗിരിയ പ്രശസ്തം"), options: [L("Sri Lankan rock fortress with fresco maidens", "ശ്രീലങ്കൻ പാറക്കോട്ടയും ഫ്രെസ്കോ നായികമാരും"), L("Assyrian lamassu gates", "അസ്സീരിയൻ ലമാസു ഗേറ്റ്"), L("Ishtar Gate of Babylon as a Sri Lankan copy", "ബാബിലോൺ ഇഷ്താർ ഗേറ്റിന്റെ ശ്രീലങ്കൻ പകർപ്പ്"), L("The Sarnath lion capital", "സാരനാഥ് സിംഹമുദ്ര")], answer: 0, explain: L("5th-c Kassapa palace-fort; the painted apsara-like figures are the usual MCQ image. South Asian, not Mesopotamian.", "5-ാം നൂ. കസ്സപ കൊട്ടാരം-കോട്ട. മെസൊപ്പൊട്ടേമിയ അല്ല."), trap: L("Any rock maiden = Ajanta.", "പാറയിലെ നായിക = അജന്ത."), fix: L("Ajanta = Buddhist vihara, India. Sigiriya = palace rock, Sri Lanka. Similar skill, different brief.", "അജന്ത ബൗദ്ധ വിഹാരം. സിഗിരിയ കൊട്ടാരപ്പാറ.") }),
  Q({ id: "va-u9-06", paper: P, unitId: "va-u9", q: L("Thangka painting is characteristic of", "തങ്ക ചിത്രം ലക്ഷണം"), options: [L("Tibetan (and related Himalayan) Buddhist scroll images, often mandala/deity", "ടിബറ്റൻ (ഹിമാലയൻ) ബൗദ്ധ സ്ക്രോൾ, മണ്ഡല/ദേവത"), L("Dutch still life only", "ഡച്ച് സ്റ്റിൽ ലൈഫ് മാത്രം"), L("Company school trades", "കമ്പനി സ്കൂൾ വ്യാപാര ചിത്രം"), L("SWAYAM certificates", "SWAYAM സർട്ടിഫിക്കറ്റ്")], answer: 0, explain: L("Cloth, mineral colour, iconometric grids. Nepal’s paubha is a cousin. Unit IX + iconometry in the art-history elective.", "തുണി, ധാതു നിറം, ഐക്കണോമെട്രിക് ഗ്രിഡ്. നേപ്പാളിലെ പൗഭ ജോടി."), trap: L("Any scroll = Chinese landscape.", "സ്ക്രോൾ = ചൈനീസ് ലാൻഡ്സ്കേപ്പ്."), fix: L("Chinese hanging scroll ≠ Tibetan thangka. Different iconography, different job (lineage/ritual vs literati).", "ചൈനീസ് സ്ക്രോൾ ≠ തങ്ക. റിച്ച്വൽ vs ലിറ്ററാറ്റി.") }),
  Q({ id: "va-u9-07", paper: P, unitId: "va-u9", q: L("Assyrian palace art is recognised by", "അസ്സീരിയൻ കൊട്ടാരക്കല തിരിച്ചറിയുന്നത്"), options: [L("Lamassu (winged human-headed bulls) and narrative relief campaigns", "ലമാസു (ചിറകുള്ള മനുഷ്യശിരസ്സുള്ള കാള)യും ആഖ്യാന റിലീഫ് യുദ്ധങ്ങളും"), L("Impressionist haystacks", "ഇംപ്രഷനിസ്റ്റ് വൈക്കോൽക്കൂന"), L("Wasli portraits of Jahangir", "ജഹാംഗീറിന്റെ വാസ്ലി പോർട്രെയ്റ്റ്"), L("Haniwa clay cylinders only", "ഹനിവ കളിമൺ സിലിണ്ടർ മാത്രം")], answer: 0, explain: L("Nimrud/Nineveh: power as procession of stone. Achaemenid Persia later reworks imperial relief at Persepolis.", "നിമ്രുദ്/നിനവേ. പിന്നീട് അക്കാമെനിഡ് പെർസെപോലിസ്."), trap: L("All ancient Near East = Egypt.", "പുരാതന സമീപപൂർവ്വം = ഈജിപ്ത്."), fix: L("Egypt canon/frontalism. Assyria narrative muscle. Persia ceremonial stair. Three Near-Eastern flavours.", "ഈജിപ്ത് കാനൻ. അസ്സീരിയ ആഖ്യാനം. പേർഷ്യ ചടങ്ങ്.") }),
  Q({ id: "va-u9-08", paper: P, unitId: "va-u9", q: L("Song-dynasty painting in China is especially associated with", "ചൈനയിലെ സോങ് രാജവംശ ചിത്രം"), options: [L("Monumental and literati landscape, mist, brush-ink values", "സ്മാരക/ലിറ്ററാറ്റി ലാൻഡ്സ്കേപ്പ്, മൂടൽമഞ്ഞ്, മഷി വാല്യൂ"), L("Only Warhol silkscreens", "വാർഹോൾ സിൽക്ക് സ്ക്രീൻ മാത്രം"), L("Only Chola bronzes", "ചോള വെങ്കലം മാത്രം"), L("Only Madhubani filling", "മധുബനി ഫില്ലിംഗ് മാത്രം")], answer: 0, explain: L("From Tang figure splendour toward Song landscape as philosophy. Later Ming/Qing continue literati debates.", "ടാങ് രൂപശ്രീയിൽ നിന്ന് സോങ് ലാൻഡ്സ്കേപ്പ് തത്ത്വചിന്തയിലേക്ക്."), trap: L("All Chinese art = terracotta army.", "എല്ലാ ചൈനീസ് കലയും ടെറാക്കോട്ട സേന."), fix: L("Shang bronze, Qin army, Tang Buddhist/figure, Song landscape — four dynasty signatures.", "ഷാങ് വെങ്കലം, ക്വിൻ സേന, ടാങ് രൂപം, സോങ് ഭൂപ്രകൃതി.") }),

  Q({ id: "va-u10-01", paper: P, unitId: "va-u10", difficulty: "jrf", q: L("Panofsky’s three strata of meaning are", "പനോഫ്സ്കിയുടെ മൂന്ന് അർഥതലം"), options: [L("Hue, value, chroma", "ഹ്യൂ, വാല്യൂ, ക്രോമ"), L("Pre-iconographic, iconographic, iconological", "പ്രീ-ഐക്കണോഗ്രാഫിക്, ഐക്കണോഗ്രാഫിക്, ഐക്കണോളജിക്കൽ"), L("Nagara, Dravida, Vesara", "നാഗര, ദ്രാവിഡ, വേസര"), L("SMTP, IMAP, POP", "SMTP, IMAP, POP")], answer: 1, explain: L("1 what we see naturally, 2 conventional stories/motifs, 3 cultural-philosophical meaning. Iconography ≠ iconology.", "1 സ്വാഭാവിക കാഴ്ച, 2 മോട്ടിഫ്/കഥ, 3 സാംസ്കാരിക അർഥം."), trap: L("Using iconography and iconology as synonyms.", "രണ്ട് പദവും പര്യായം."), fix: L("Graphy lists. Logy interprets. Third level = iconology.", "Graphy ലിസ്റ്റ്. Logy വ്യാഖ്യാനം.") }),
  Q({ id: "va-u10-02", paper: P, unitId: "va-u10", q: L("Warli painting is associated with", "വാർലി ചിത്രം"), options: [L("Maharashtra — white rice paste, geometric humans on earthen ground", "മഹാരാഷ്ട്ര — വെളുത്ത അരി പേസ്റ്റ്, ജ്യാമിതീയ മനുഷ്യർ ചെളിഗ്രൗണ്ടിൽ"), L("Kerala mural only", "കേരള മ്യൂറൽ മാത്രം"), L("Ukiyo-e publishers", "ഉക്യോ-ഇ പ്രസാധകർ"), L("Ashokan edicts", "അശോകൻ ശാസനം")], answer: 0, explain: L("Circle-triangle-square cosmology. Do not confuse with Madhubani (Bihar, filled line, Hindu/folk narrative) or Gond (MP, dotted line, Jangarh).", "വൃത്ത-ത്രികോണ-ചതുരം. മധുബനി/ഗോണ്ട് അല്ല."), trap: L("All folk = Madhubani, because it is the most printed.", "എല്ലാ നാടനും മധുബനി — ഏറ്റവും അച്ചടിച്ചത്."), fix: L("State–form pairs on a map: Warli-MH, Mithila-Bihar, Gond-MP, Pata-Odisha/Bengal, Phad-Rajasthan, Kalamkari-AP.", "സംസ്ഥാന–രൂപ ജോടി ഭൂപടത്തിൽ.") }),
  Q({ id: "va-u10-03", paper: P, unitId: "va-u10", q: L("Gestalt psychology contributes to art analysis the idea that", "ഗെസ്റ്റാൾട്ട് കലാവിശകലനത്തിന് നൽകുന്നത്"), options: [L("We perceive organised wholes — proximity, similarity, closure, figure-ground", "നാം സംഘടിത മൊത്തങ്ങൾ ഗ്രഹിക്കുന്നു — സാമീപ്യം, സാദൃശ്യം, ക്ലോഷർ, ഫിഗർ-ഗ്രൗണ്ട്"), L("Only class struggle explains pictures", "ചിത്രം വിശദീകരിക്കുന്നത് വർഗസമരം മാത്രം"), L("Beauty is a pramana", "ഭംഗി ഒരു പ്രമാണം"), L("Museums should be abolished by definition", "മ്യൂസിയം നിർവചനത്താൽ നിർത്തലാക്കണം")], answer: 0, explain: L("Perception laws that Unit I composition already uses. Syllabus places Gestalt in Unit X methods.", "യൂണിറ്റ് I കമ്പോസിഷൻ ഉപയോഗിക്കുന്ന ഗ്രഹണ നിയമങ്ങൾ. സിലബസ് യൂണിറ്റ് X-ൽ."), trap: L("Gestalt = German Expressionism.", "ഗെസ്റ്റാൾട്ട് = ജർമ്മൻ എക്സ്പ്രഷനിസം."), fix: L("Gestalt = how we group what we see. Expressionism = how we distort what we feel.", "ഗെസ്റ്റാൾട്ട് ഗ്രൂപ്പിംഗ്. എക്സ്പ്രഷനിസം വികാരവിള്ളൽ.") }),
  Q({ id: "va-u10-04", paper: P, unitId: "va-u10", q: L("Formalism in art history (e.g. Wölfflin / later Greenberg) emphasises", "കലാചരിത്രത്തിലെ ഫോർമലിസം ഊന്നുന്നത്"), options: [L("Social class as the only cause", "വർഗം മാത്രം കാരണം"), L("Looking at form — line, plane, colour, medium — before story", "കഥയ്ക്ക് മുമ്പ് രൂപം — രേഖ, തലം, നിറം, മാധ്യമം"), L("Only artist biography gossip", "ജീവചരിത്ര ഗോസിപ്പ് മാത്രം"), L("Only GI tags", "GI ടാഗ് മാത്രം")], answer: 1, explain: L("Useful and limited. New Art History (class, gender, deconstruction) arrived as a critique of this self-sufficiency.", "ഉപയോഗപ്രദവും പരിമിതവും. ന്യൂ ആർട്ട് ഹിസ്റ്ററി ഇതിന്റെ സ്വയംപര്യാപ്തതയെ വിമർശിച്ച് വന്നു."), trap: L("Formalism = ‘against all meaning’ as a slur, so students refuse the option.", "ഫോർമലിസം = അർഥവിരുദ്ധം എന്ന ആക്ഷേപം."), fix: L("Formalism = start with how it looks. Iconology = ask what it meant. Marxism = ask who paid. Keep the ladder.", "ഫോർമലിസം കാഴ്ച. ഐക്കണോളജി അർഥം. മാർക്സിസം പണം. ഏണി സൂക്ഷിക്കുക.") }),
  Q({ id: "va-u10-05", paper: P, unitId: "va-u10", predicted: true, q: L("Jangarh Singh Shyam is a landmark in", "ജംഗഢ് സിംഗ് ശ്യാം നാഴികക്കല്ല്"), options: [L("The contemporary transformation of Gond painting into a named modern practice", "ഗോണ്ട് ചിത്രത്തിന്റെ സമകാലിക നാമമുള്ള ആധുനിക പ്രാക്ടീസിലേക്കുള്ള രൂപാന്തരം"), L("Ashokan pillar edicts", "അശോകൻ ശാസനം"), L("PAG oil portraiture of 1947 only", "1947 PAG ഓയിൽ മാത്രം"), L("Ukiyo-e actor busts", "ഉക്യോ-ഇ നടൻ ബസ്റ്റ്")], answer: 0, explain: L("Bharhut/Patangarh Gond; Swaminathan/Bharat Bhavan moment. Unit X ‘transformations of folk/tribal’. Tragic biography is extra; the exam wants the art-historical job.", "ഗോണ്ട്; സ്വാമിനാഥൻ/ഭാരത് ഭവൻ. യൂണിറ്റ് X നാടൻ രൂപാന്തരം."), trap: L("Folk must stay anonymous — so a named Gond artist ‘cannot’ be the answer.", "നാടൻ അജ്ഞാതമായിരിക്കണം — പേരുള്ള ഗോണ്ട് ആർട്ടിസ്റ്റ് ഉത്തരമാകില്ല എന്ന്."), fix: L("Syllabus says contemporary practices of traditional communities. Named modern folk-artists are inside, not outside.", "പേരുള്ള ആധുനിക നാടൻ കലാകാരർ സിലബസിനകത്ത്.") }),
  Q({ id: "va-u10-06", paper: P, unitId: "va-u10", q: L("A curator in the syllabus sense works at the confluence of", "സിലബസിലെ ക്യുറേറ്റർ ലയിക്കുന്നത്"), options: [L("Only frame-making shops", "ഫ്രെയിം കടകൾ മാത്രം"), L("Museum, gallery and art history — collection, display, interpretation, sometimes market", "മ്യൂസിയം, ഗാലറി, കലാചരിത്രം — ശേഖരം, പ്രദർശനം, വ്യാഖ്യാനം, ചിലപ്പോൾ വിപണി"), L("Only lost-wax foundries", "ലോസ്റ്റ്-വാക്സ് ലോഹശാല മാത്രം"), L("Only UGC-NET paper setting", "യുജിസി-നെറ്റ് ചോദ്യപേപ്പർ മാത്രം")], answer: 1, explain: L("The official unit names this confluence. Biennale curator commissions; museum curator conserves and educates; gallery curator also sells. Related, not identical.", "ബിനാലെ കമ്മീഷൻ; മ്യൂസിയം കൺസർവ്; ഗാലറി വിൽപന. ബന്ധമുണ്ട്, ഒന്നല്ല."), trap: L("Curator = decorator.", "ക്യുറേറ്റർ = ഡെക്കറേറ്റർ."), fix: L("Three institutions, three verbs: conserve (museum), sell (gallery), commission/theme (biennale).", "മൂന്ന് സ്ഥാപനം, മൂന്ന് ക്രിയ.") }),
  Q({ id: "va-u10-07", paper: P, unitId: "va-u10", q: L("New Art History typically brings in", "ന്യൂ ആർട്ട് ഹിസ്റ്ററി കൊണ്ടുവരുന്നത്"), options: [L("Class, gender, semiotics, deconstruction — against a purely connoisseurial story", "വർഗം, ലിംഗം, സെമിയോട്ടിക്സ്, ഡീകൺസ്ട്രക്ഷൻ — കേവല രസിക വൃത്താന്തത്തിന് എതിരെ"), L("Only more accurate varnish recipes", "കൂടുതൽ കൃത്യമായ വാർണിഷ് റെസിപ്പി മാത്രം"), L("Abolition of all dates", "എല്ലാ തീയതിയും നിർത്തലാക്കൽ"), L("Mandatory Sanskrit slokas in every caption", "ഓരോ ക്യാപ്ഷനിലും നിർബന്ധ സംസ്കൃത ശ്ലോകം")], answer: 0, explain: L("T.J. Clark, Griselda Pollock, Derridean reading — meaning is social and unstable. Complements, not erases, close looking.", "അർഥം സാമൂഹികവും അസ്ഥിരവും. ക്ലോസ് ലുക്കിംഗ് മായ്ക്കുന്നില്ല, പൂരിപ്പിക്കുന്നു."), trap: L("New = reject all older methods, so formalism questions have no answer.", "ന്യൂ = പഴയത് വേണ്ട — ഫോർമലിസം ചോദ്യത്തിന് ഉത്തരമില്ല."), fix: L("JRF wants you to name methods, not pick a team. Formalism AND feminism can both be correct in different stems.", "മെത്തേഡിന് പേരിടുക, ടീം പിടിക്കരുത്.") }),
  Q({ id: "va-u10-08", paper: P, unitId: "va-u10", q: L("Madhubani / Mithila painting is primarily rooted in", "മധുബനി / മിഥില ചിത്രം പ്രധാനമായും"), options: [L("Bihar — line, fill, ritual wall/paper, Hindu-folk narrative", "ബീഹാർ — രേഖ, ഫിൽ, റിച്ച്വൽ ചുവർ/കടലാസ്, ഹൈന്ദവ-നാടൻ ആഖ്യാനം"), L("Edo actor portraits", "എഡോ നടൻ പോർട്രെയ്റ്റ്"), L("Qin tomb pits", "ക്വിൻ ശവകുടീരം"), L("Cabaret Voltaire posters", "കബറേ വോൾട്ടയർ പോസ്റ്റർ")], answer: 0, explain: L("Women’s courtyard tradition that entered paper/market in the 20th century — another ‘transformation’ example beside Gond and Warli.", "സ്ത്രീകളുടെ മുറ്റ പാരമ്പര്യം 20-ാം നൂറ്റാണ്ടിൽ കടലാസ്/വിപണിയിലേക്ക്. ഗോണ്ട്/വാർലി പോലെ രൂപാന്തര ഉദാഹരണം."), trap: L("Bihar → Nalanda only, so folk of Bihar disappears.", "ബീഹാർ → നാലന്ത മാത്രം, നാടൻ മറയുന്നു."), fix: L("Bihar hosts both Nalanda (Unit VII/P1-X) and Mithila (Unit X). One state, two syllabus rooms.", "ബീഹാറിൽ നാലന്തയും മിഥിലയും. ഒരു സംസ്ഥാനം, രണ്ട് മുറി.") }),
];
